  useEffect(() => {
    invoke('get_shortcut', { name: 'update_shortcut' }).then((res: any) => { if (res) setShortcut(res); }).catch(()=>{});
    invoke('get_shortcut', { name: 'update_snip_shortcut' }).then((res: any) => { if (res) setSnipShortcut(res); }).catch(()=>{});
    invoke('get_shortcut', { name: 'update_text_shortcut' }).then((res: any) => { if (res) setTextShortcut(res); }).catch(()=>{});
    invoke('get_shortcut', { name: 'update_search_shortcut' }).then((res: any) => { if (res) setSearchShortcut(res); }).catch(()=>{});
    invoke('get_shortcut', { name: 'update_trigger_shortcut' }).then((res: any) => { if (res) { setTriggerShortcut(res); localStorage.setItem('drawer_trigger_shortcut', res); } }).catch(()=>{});
    invoke('get_shortcut', { name: 'update_note_shortcut' }).then((res: any) => { if (res) setNoteShortcut(res); }).catch(()=>{});
    invoke('get_shortcut', { name: 'update_canvas_shortcut' }).then((res: any) => { if (res) setCanvasShortcut(res); }).catch(()=>{});
    invoke('get_auto_start').then((res: any) => setIsAutoStart(!!res)).catch(()=>{});
    invoke('get_local_ip').then((res: any) => setLocalIP(String(res || ''))).catch(()=>{});
    invoke('get_mobile_pair_url').then((res: any) => setMobilePairUrl(String(res || ''))).catch(()=>{});
    invoke('set_topmost', { topmost: true }).catch(()=>{});
    void refreshLicenseStatus(true);
    if (!cloudStartupSyncStartedRef.current) {
      cloudStartupSyncStartedRef.current = true;
      void refreshCloudAccount(true)
        .catch((err) => {
          console.warn('云端授权同步失败，将按当前本地授权状态继续:', err);
          void refreshLicenseStatus(true);
        });
    }
  }, []);

  const handleOpenTextInput = () => { setIsDrawerAgentOpen(false); setShowTextInput(true); setShowWebImageCollector(false); setIsSearchActive(false); setShowSettings(false); setShowFolderModal(false); };
  const normalizeWebImageCollectorTag = (value: string) => (
    String(value || '')
      .trim()
      .replace(/[，、,]+/g, ' ')
      .replace(/\s+/g, ' ')
      .slice(0, 24)
  );

  const normalizeWebImageCollectorTags = (values: string[]) => {
    const tags: string[] = [];
    values.forEach(value => {
      const clean = normalizeWebImageCollectorTag(value);
      if (!clean || tags.includes(clean)) return;
      tags.push(clean);
    });
    return tags.slice(0, 8);
  };

  const splitWebImageTagsFromQuery = (query: string) => normalizeWebImageCollectorTags(
    String(query || '')
      .split(/[，,、\s]+/)
      .filter(Boolean),
  );

  const normalizeRemoteImageSearchDescription = (value: unknown): WebImageSearchDescription => {
    if (typeof value === 'string') {
      const query = value.trim().replace(/\s+/g, ' ');
      return {
        query,
        tags: splitWebImageTagsFromQuery(query),
        source: 'siliconflow',
      };
    }

    const data = value && typeof value === 'object' ? value as Record<string, unknown> : {};
    const query = String(data.query || '').trim().replace(/\s+/g, ' ');
    const subject = normalizeWebImageCollectorTag(String(data.subject || ''));
    const style = normalizeWebImageCollectorTag(String(data.style || ''));
    const modelTags = Array.isArray(data.tags) ? data.tags.map(tag => String(tag || '')) : [];
    const tags = normalizeWebImageCollectorTags([
      subject,
      style,
      ...modelTags,
      ...(query ? splitWebImageTagsFromQuery(query) : []),
    ]);

    return {
      query: query || tags.join(' '),
      tags,
      subject,
      style,
      source: 'siliconflow',
    };
  };

  const normalizeLocalVlmImageSearchDescription = (value: unknown): WebImageSearchDescription => ({
    ...normalizeRemoteImageSearchDescription(value),
    source: 'ollama',
  });

  const webImageSearchSourceLabel = (source: WebImageSearchDescription['source']) => {
    if (source === 'ollama') return '本地大模型';
    return '硅基流动';
  };

  const applyWebImageCollectorTags = (values: string[], fallbackQuery = '') => {
    const tags = normalizeWebImageCollectorTags(values);
    const query = tags.length ? tags.join(' ') : String(fallbackQuery || '').trim().replace(/\s+/g, ' ');
    setWebImageCollectorTags(tags);
    setWebImageCollectorQuery(query);
    return { tags, query };
  };

  const updateWebImageCollectorTag = (index: number, value: string) => {
    const next = [...webImageCollectorTags];
    next[index] = value.replace(/[，、,]+/g, ' ').slice(0, 24);
    applyWebImageCollectorTags(next, webImageCollectorQuery);
  };

  const removeWebImageCollectorTag = (index: number) => {
    applyWebImageCollectorTags(webImageCollectorTags.filter((_, itemIndex) => itemIndex !== index), webImageCollectorQuery);
  };

  const addWebImageCollectorTag = (value = webImageCollectorTagDraft) => {
    const parts = String(value || '').split(/[，,、\n]+/).filter(Boolean);
    if (parts.length === 0) return;
    applyWebImageCollectorTags([...webImageCollectorTags, ...parts], webImageCollectorQuery);
    setWebImageCollectorTagDraft('');
  };

  const clearWebImageCollectorTags = () => {
    setWebImageCollectorTags([]);
    setWebImageCollectorTagDraft('');
  };

  const openWebImageCollector = (reference: WebImageCollectorReference | null = null) => {
    if (isCollectingWebImages || isGeneratingWebImageQuery) return;
    setIsDrawerAgentOpen(false);
    setWebImageCollectorReference(reference);
    setWebImageCollectorStatus('');
    setShowWebImageCollector(true);
    setShowTextInput(false);
    setIsSearchActive(false);
    setShowSettings(false);
    setShowFolderModal(false);
    setShowMoveFolderModal(false);
    setIsOpen(true);
  };

  const openWebImageCollectorWithReference = (reference: WebImageCollectorReference, toastMessage = '已把这张图设为收图参考图') => {
    if (isCollectingWebImages || isGeneratingWebImageQuery) {
      showToast('正在收图或识别参考图，请稍后再试');
      return;
    }
    setWebImageCollectorQuery('');
    clearWebImageCollectorTags();
    openWebImageCollector(reference);
    showToast(toastMessage);
  };

  const closeWebImageCollector = () => {
    if (isCollectingWebImages || isGeneratingWebImageQuery) return;
    setShowWebImageCollector(false);
    setWebImageCollectorReference(null);
    setWebImageCollectorStatus('');
    setWebImageCollectorQuery('');
    clearWebImageCollectorTags();
  };

  useEffect(() => {
    if (!showWebImageCollector) return;
    const handleOutsidePointerDown = (event: PointerEvent) => {
      const target = event.target;
      if (!(target instanceof Node) || webImageCollectorPanelRef.current?.contains(target)) return;
      closeWebImageCollector();
    };
    document.addEventListener('pointerdown', handleOutsidePointerDown, true);
    return () => document.removeEventListener('pointerdown', handleOutsidePointerDown, true);
  }, [showWebImageCollector, isCollectingWebImages, isGeneratingWebImageQuery]);

  const announceLocalVisionModelReady = (options: { force?: boolean } = {}) => {
    if ((!options.force && !localVisionModelDownloadStartedRef.current) || localVisionModelReadyNotifiedRef.current) return;
    localVisionModelReadyNotifiedRef.current = true;
    const message = '本地大模型已准备好，可以用参考图搜图了';
    setLocalVisionModelLastError('');
    setWebImageCollectorStatus(prev => prev ? message : prev);
    showToast(message);
    void invoke('show_system_notification', {
      title: '本地大模型已下载完成',
      body: '参考图搜图现在可以使用了。',
    }).catch((err) => console.warn('本地大模型完成通知发送失败:', err));
    setIsOpen(true);
    void invoke('open_drawer', {
      width: drawerWidthRef.current,
      height: drawerHeightRef.current,
      mode: triggerModeRef.current,
    }).catch((err) => console.warn('本地大模型完成后打开抽屉失败:', err));
  };

  const handleLocalVisionModelProgress = (progress: { stage?: string; message: string; progress?: number }) => {
    const message = progress.message || '正在准备本地大模型';
    const shouldHideDuringWebCollect = isCollectingWebImagesRef.current;
    if (progress.stage === 'downloading' || /下载|拉取/.test(message)) {
      localVisionModelPreparingRef.current = true;
      localVisionModelDownloadStartedRef.current = true;
      setLocalVisionModelLastError('');
    }
    if (progress.stage === 'checking' || progress.stage === 'starting' || progress.stage === 'installing') {
      localVisionModelPreparingRef.current = true;
      setLocalVisionModelLastError('');
    }
    if (/正在识别/.test(message)) {
      if (showWebImageCollector && !shouldHideDuringWebCollect) setWebImageCollectorStatus(message);
      return;
    }
    const hasProgress = Number.isFinite(progress.progress);
    const isReady = /已就绪|已下载完成/.test(message);
    setLocalVisionModelDownload(prev => {
      const isDownloading = progress.stage === 'downloading' || /下载|拉取/.test(message);
      const value = hasProgress
        ? clamp(Number(progress.progress), 0, 100)
        : (prev.visible ? prev.progress : 3);
      return {
        visible: isDownloading && !isReady && !shouldHideDuringWebCollect,
        message,
        progress: isReady ? 100 : value,
        phase: isReady ? 'ready' : isDownloading ? 'downloading' : progress.stage === 'installing' ? 'loading' : 'loading',
        startedAt: isReady ? prev.startedAt : (prev.visible && prev.startedAt ? prev.startedAt : Date.now()),
        updatedAt: Date.now(),
      };
    });
    if (isReady) {
      localVisionModelReadyRef.current = true;
      localVisionModelPreparingRef.current = false;
      setLocalVisionModelLastError('');
      announceLocalVisionModelReady();
      window.setTimeout(() => {
        setLocalVisionModelDownload(prev => prev.phase === 'ready' ? { ...prev, visible: false, startedAt: undefined, updatedAt: Date.now() } : prev);
      }, 900);
    }
    if (showWebImageCollector && !shouldHideDuringWebCollect) setWebImageCollectorStatus(message);
  };

  const showLocalVisionModelError = (err: unknown, options: { silent?: boolean } = {}) => {
    const message = `本地大模型不可用：${err instanceof Error ? err.message : String(err || '请检查 Ollama 后重试')}`;
    localVisionModelReadyRef.current = false;
    localVisionModelPreparingRef.current = false;
    setLocalVisionModelLastError(message);
    if (options.silent) {
      setLocalVisionModelDownload(prev => ({ ...prev, visible: false, phase: 'idle', updatedAt: Date.now() }));
      console.warn(message);
      return;
    }
    setLocalVisionModelDownload({
      visible: true,
      message,
      progress: 0,
      phase: 'error',
      startedAt: Date.now(),
      updatedAt: Date.now(),
    });
    window.setTimeout(() => {
      setLocalVisionModelDownload(prev => prev.phase === 'error' ? { ...prev, visible: false, startedAt: undefined, updatedAt: Date.now() } : prev);
    }, 5200);
    if (showWebImageCollector) setWebImageCollectorStatus(message);
  };

  const checkLocalVisionModelStatus = async (options: { silent?: boolean } = {}) => {
    const model = getStoredLocalVisionModel();
    setIsLocalVisionModelChecking(true);
    try {
      const status = await invoke<LocalVisionModelStatusPayload>('get_local_vision_model_status', { model });
      const ready = !!status?.ready;
      localVisionModelReadyRef.current = ready;
      localVisionModelPreparingRef.current = false;
      if (ready) {
        setLocalVisionModelLastError('');
        setLocalVisionModelDownload(prev => ({
          ...prev,
          visible: false,
          message: '本地大模型已就绪',
          progress: 100,
          phase: 'ready',
          updatedAt: Date.now(),
        }));
      } else {
        setLocalVisionModelDownload(prev => ({
          ...prev,
          visible: false,
          message: '本地大模型增量包未下载',
          progress: 0,
          phase: 'idle',
          updatedAt: Date.now(),
        }));
      }
      return ready;
    } catch (err) {
      localVisionModelReadyRef.current = false;
      localVisionModelPreparingRef.current = false;
      if (!options.silent) showLocalVisionModelError(err, { silent: true });
      return false;
    } finally {
      setIsLocalVisionModelChecking(false);
    }
  };

  const ensureLocalVisionModel = (options: { silent?: boolean; toast?: boolean; notifyReady?: boolean } = {}) => {
    if (localVisionModelReadyRef.current) return Promise.resolve();
    if (localVisionModelEnsurePromiseRef.current) return localVisionModelEnsurePromiseRef.current;

    const model = getStoredLocalVisionModel();
    localVisionModelPreparingRef.current = true;
    setLocalVisionModelLastError('');
    localVisionModelDownloadStartedRef.current = true;
    if (options.toast) showToast('正在下载本地大模型增量包');

    const promise = invoke('ensure_ollama_vision_model', { model })
      .then(() => {
        localVisionModelReadyRef.current = true;
        localVisionModelPreparingRef.current = false;
        setLocalVisionModelLastError('');
        setLocalVisionModelDownload(prev => ({
          ...prev,
          visible: false,
          message: '本地大模型已就绪',
          progress: 100,
          phase: 'ready',
          updatedAt: Date.now(),
        }));
        if (options.notifyReady) announceLocalVisionModelReady({ force: true });
      })
      .catch((err) => {
        showLocalVisionModelError(err, { silent: options.silent ?? true });
        throw err;
      })
      .finally(() => {
        localVisionModelEnsurePromiseRef.current = null;
      });

    localVisionModelEnsurePromiseRef.current = promise;
    return promise;
  };

  const retryLocalVisionModelDownload = async () => {
    setWebImageCollectorStatus('正在下载本地大模型增量包');
    try {
      await ensureLocalVisionModel({ silent: false, toast: true, notifyReady: true });
      showToast('本地大模型已准备好');
    } catch (_) {
      showToast('增量包下载失败，请先安装或启动 Ollama');
    }
  };

  const installOllamaSilently = async () => {
    if (isInstallingOllama) return;
    setIsInstallingOllama(true);
    localVisionModelPreparingRef.current = true;
    setLocalVisionModelLastError('');
    setLocalVisionModelDownload(prev => ({
      ...prev,
      visible: false,
      message: '正在静默安装 Ollama',
      progress: Math.max(prev.progress || 0, 2),
      phase: 'loading',
      updatedAt: Date.now(),
    }));
    showToast('正在静默安装 Ollama');
    try {
      await invoke('install_ollama_silent');
      showToast('Ollama 已安装，开始下载增量包');
      await ensureLocalVisionModel({ silent: false, toast: true, notifyReady: true });
    } catch (err) {
      console.warn('静默安装 Ollama 失败:', err);
      showLocalVisionModelError(err, { silent: false });
      showToast('静默安装失败，可打开下载页手动安装');
    } finally {
      setIsInstallingOllama(false);
    }
  };

  const openOllamaDownloadPage = async () => {
    try {
      await openUrl('https://ollama.com/download/windows');
    } catch (err) {
      console.warn('打开 Ollama 下载页失败:', err);
      showToast('无法打开 Ollama 下载页');
    }
  };

  useEffect(() => {
    let cancelled = false;
    let unlisten: (() => void) | undefined;

    const startLocalVisionModelStatusWatcher = async () => {
      try {
        const cleanup = await listen<LocalVisionModelProgressPayload>('local-vision-model-progress', (event) => {
          if (cancelled) return;
          const payload = event.payload || {};
          handleLocalVisionModelProgress({
            stage: payload.stage,
            message: payload.message || '正在准备本地大模型',
            progress: typeof payload.progress === 'number' ? payload.progress : undefined,
          });
        });
        if (cancelled) {
          cleanup();
          return;
        }
        unlisten = cleanup;
      } catch (err) {
        console.warn('监听本地大模型下载进度失败:', err);
      }

      if (!cancelled) void checkLocalVisionModelStatus({ silent: true });
    };

    void startLocalVisionModelStatusWatcher();

    return () => {
      cancelled = true;
      unlisten?.();
    };
  }, []);

  const collectWebImagesToDrawer = async (queryOverride?: string) => {
    const query = (queryOverride ?? webImageCollectorQuery).trim().replace(/\s+/g, ' ');
    if (!query || isCollectingWebImages) return;
    const folderName = query.slice(0, 32);
    const existingFolder = foldersRef.current.find(folder => folder.name === folderName);
    const folder: Folder = existingFolder || {
      id: createAssetId(),
      name: folderName,
      color: '#0ea5e9',
    };
    const latestCacheDir = await getLatestFileCacheDir();

    setIsCollectingWebImages(true);
    setLocalVisionModelDownload(prev => ({ ...prev, visible: false, updatedAt: Date.now() }));
    showToast(`开始收集「${query}」图片`);
    try {
      const collected = await invoke<CollectedWebImage[]>('collect_web_images', {
        query,
        count: 10,
        dir: latestCacheDir || undefined,
      });
      if (!Array.isArray(collected) || collected.length === 0) {
        showToast('没有收集到可用图片');
        return;
      }

      const now = Date.now();
      const newItems = collected.map((image, index) => {
        const fileName = image.path.split(/[\\/]/).pop() || `${folderName}_${index + 1}.jpg`;
        return {
          id: `web_collect_${createAssetId()}`,
          type: 'image',
          content: image.title || fileName,
          name: image.title || fileName,
          path: image.path,
          url: convertFileSrc(image.path),
          sourceUrl: image.imageUrl,
          originalUrl: image.imageUrl,
          pageUrl: image.pageUrl || undefined,
          createdAt: now + index,
          isQuickAccess: false,
          folderId: folder.id,
        } as BufferItem;
      });

      pushDrawerUndoSnapshot('网络收集图片');
      if (!existingFolder) {
        setFolders(prev => {
          if (prev.some(item => item.id === folder.id || item.name === folder.name)) return prev;
          const nextFolders = insertDrawerFolderAtTop(prev, folder);
          persistFoldersSnapshot(nextFolders);
          return nextFolders;
        });
      }
      setItems(prev => [...newItems, ...prev]);
      enqueueAutoAiTaggingForItems(newItems);
      setActiveFolderId(folder.id);
      setActiveTab('image');
      setShowWebImageCollector(false);
      setWebImageCollectorQuery('');
      setWebImageCollectorReference(null);
      clearWebImageCollectorTags();
      setIsOpen(true);
      showToast(`已收集 ${newItems.length} 张图片到「${folder.name}」`);
    } catch (err) {
      console.warn('网络图片收集失败:', err);
      showToast(`收集失败：${err instanceof Error ? err.message : String(err || '请稍后重试')}`);
    } finally {
      setIsCollectingWebImages(false);
    }
  };

  const describeReferenceImageForSearch = async (reference: WebImageCollectorReference, hint: string): Promise<WebImageSearchDescription> => {
    const browserReadableSource = reference.preview || reference.source;
    let aiReadableSource = reference.source;
    let localSource = '';
    try {
      localSource = await imageSourceToModelDataUrl(browserReadableSource);
      if (localSource) aiReadableSource = localSource;
    } catch (imageErr) {
      console.warn('参考图读取失败，将尝试使用原始路径:', imageErr);
    }

    if (hasRemoteImageSearch()) {
      setWebImageCollectorStatus(`正在使用 ${remoteImageSearchLabel()} 识别参考图`);
      try {
        const remoteResult = await invoke<unknown>('describe_image_for_search', {
          imageSource: aiReadableSource,
          hint: hint.trim() || undefined,
          apiConfig: getAiAnalysisConfig(),
        });
        const description = normalizeRemoteImageSearchDescription(remoteResult);
        if (description.query.trim()) return description;
      } catch (remoteErr) {
        console.warn('云端视觉模型参考图识别失败:', remoteErr);
        if (!localVisionModelReadyRef.current) {
          const remoteMessage = remoteErr instanceof Error ? remoteErr.message : String(remoteErr || '请检查视觉模型配置');
          throw new Error(`云端视觉模型识别失败：${remoteMessage}`);
        }
      }
    }

    if (localVisionModelReadyRef.current) {
      setWebImageCollectorStatus('正在使用本地大模型识别参考图');
      try {
        const localVlmResult = await invoke<unknown>('describe_image_for_search_local_vlm', {
          imageSource: aiReadableSource,
          hint: hint.trim() || undefined,
          model: getStoredLocalVisionModel(),
        });
        const description = normalizeLocalVlmImageSearchDescription(localVlmResult);
        if (description.query.trim()) return description;
      } catch (vlmErr) {
        console.warn('本地 Ollama 视觉大模型识别失败:', vlmErr);
        showLocalVisionModelError(vlmErr);
        const vlmMessage = vlmErr instanceof Error ? vlmErr.message : String(vlmErr || '请检查 Ollama 本地视觉模型');
        throw new Error(`本地大模型识别失败：${vlmMessage}`);
      }
    }

    throw new Error('请先在设置里配置硅基流动视觉模型，或下载本地大模型增量包后再按参考图搜图。');
  };

  const generateQueryAndCollectFromReference = async (reference: WebImageCollectorReference | null = webImageCollectorReference, hintOverride?: string) => {
    if (!reference?.source || isGeneratingWebImageQuery || isCollectingWebImages) return;

    if (!hasRemoteImageSearch() && !localVisionModelReadyRef.current) {
      const message = localVisionModelPreparingRef.current
        ? '本地大模型增量包正在下载，下载完成后会通知你。'
        : localVisionModelLastError
        ? localVisionModelLastError
        : '请先在设置里配置硅基流动视觉模型，或下载本地大模型增量包后再按参考图搜图。';
      setWebImageCollectorStatus(message);
      setShowWebImageCollector(true);
      setShowTextInput(false);
      setIsSearchActive(false);
      setShowSettings(true);
      setActiveSettingCategory('ai-overview');
      setShowFolderModal(false);
      setShowMoveFolderModal(false);
      setIsOpen(true);
      showToast(message);
      return;
    }

    setIsGeneratingWebImageQuery(true);
    setWebImageCollectorStatus(hasRemoteImageSearch() ? '正在使用云端视觉模型识别参考图' : '正在使用本地大模型识别参考图');
    setShowWebImageCollector(true);
    setShowTextInput(false);
    setIsSearchActive(false);
    setShowSettings(false);
    setShowFolderModal(false);
    setShowMoveFolderModal(false);
    setIsOpen(true);
    showToast(hasRemoteImageSearch() ? '正在用云端视觉模型识别参考图' : '正在用本地大模型识别参考图');
    try {
      const described = await describeReferenceImageForSearch(reference, hintOverride ?? webImageCollectorQuery);
      const query = described.query;
      const cleanQuery = String(query || '').trim().replace(/\s+/g, ' ');
      if (!cleanQuery) {
        showToast('没有生成可用的搜图关键词');
        return;
      }
      const recognizedTags = described.tags?.length ? described.tags : splitWebImageTagsFromQuery(cleanQuery);
      const applied = applyWebImageCollectorTags(recognizedTags, cleanQuery);
      setWebImageCollectorTagDraft('');
      setWebImageCollectorStatus(applied.tags.length > 0 ? '已识别标签，可修改后点击开始收集' : '已生成关键词，可修改后点击开始收集');
      showToast(`${webImageSearchSourceLabel(described.source)}已识别标签，可修改后收集`);
    } catch (err) {
      console.warn('按参考图收图失败:', err);
      setWebImageCollectorStatus('');
      showToast(`按图收图失败：${err instanceof Error ? err.message : String(err || '请稍后重试')}`);
    } finally {
      setIsGeneratingWebImageQuery(false);
    }
  };

  const chooseReferenceImageForCollector = async () => {
    if (isGeneratingWebImageQuery || isCollectingWebImages) return;
    try {
      const selected = await open({
        multiple: false,
        filters: [{ name: 'Image', extensions: ['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'svg'] }],
      });
      if (typeof selected !== 'string') return;
      const name = selected.split(/[\\/]/).pop() || '参考图';
      setWebImageCollectorQuery('');
      clearWebImageCollectorTags();
      setWebImageCollectorStatus('');
      setWebImageCollectorReference({
        source: selected,
        name,
        preview: convertFileSrc(selected),
      });
    } catch (err) {
      console.warn('选择参考图失败:', err);
      showToast('选择参考图失败');
    }
  };

  const collectSimilarImagesFromItem = (item: BufferItem) => {
    if (item.type !== 'image') return;
    const source = item.path || item.originalUrl || item.sourceUrl || item.url || item.thumbnail || '';
    if (!source) {
      showToast('这张图没有可用来源，不能按图收图');
      return;
    }
    const reference = {
      source,
      name: item.name || item.content || '参考图',
      preview: item.url || item.thumbnail || (item.path ? convertFileSrc(item.path) : ''),
      itemId: item.id,
    };
    openWebImageCollectorWithReference(reference);
  };

  const handleOpenFolderModal = (parentId?: string) => {
    const parent = parentId ? foldersRef.current.find(folder => folder.id === parentId) : null;
    setNewFolderParentId(parent?.id || null);
    setNewFolderName('');
    setShowFolderModal(true);
    setFolderContextMenu(null);
    setShowMoveExistingFolderModal(false);
    setShowWebImageCollector(false);
    setIsSearchActive(false);
    setShowSettings(false);
    setShowTextInput(false);
  };
  const closeFolderModal = () => {
    setShowFolderModal(false);
    setNewFolderName('');
    setNewFolderParentId(null);
  };
  const commitQuickText = () => {
    if (!quickText.trim()) return;
    const newItem: BufferItem = createTextOrUrlItem(quickText, '灵感笔记');
    pushDrawerUndoSnapshot('新增文字');
    setItems(prev => [newItem, ...prev]);
    setActiveTab('text');
    setQuickText('');
    handleCloseTextInput();
  };
  const activateSearch = () => {
    setIsSearchActive(true);
    setShowSettings(false);
    setShowTextInput(false);
    setShowWebImageCollector(false);
    setShowFolderModal(false);
  };
  const toggleSearch = () => {
    if (!isSearchActive) {
      activateSearch();
      setTimeout(() => searchInputRef.current?.focus(), 100);
    } else {
      setIsSearchActive(false);
      setSearchQuery('');
      searchInputRef.current?.blur();
    }
  };
  const toggleSettings = () => {
    if (!showSettings) {
      setIsDrawerAgentOpen(false);
      setShowSettings(true); setIsSearchActive(false); setShowTextInput(false); setShowWebImageCollector(false); setShowFolderModal(false);
    } else {
      setShowSettings(false);
    }
  };

  useEffect(() => {
    if (!showSettings) return;
    const closeSettingsOnOutsidePointer = (event: PointerEvent) => {
      const target = event.target as HTMLElement | null;
      if (
        target?.closest('[data-drawer-settings-panel="true"]') ||
        target?.closest('[data-drawer-settings-toggle="true"]')
      ) {
        return;
      }
      setShowSettings(false);
    };

    document.addEventListener('pointerdown', closeSettingsOnOutsidePointer, true);
    return () => {
      document.removeEventListener('pointerdown', closeSettingsOnOutsidePointer, true);
    };
  }, [showSettings]);

  useEffect(() => {
    if (!folderContextMenu) return;
    const closeFolderContextMenu = (event: PointerEvent) => {
      const target = event.target as HTMLElement | null;
      if (target?.closest('[data-folder-context-menu="true"]')) return;
      setFolderContextMenu(null);
    };
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setFolderContextMenu(null);
    };
    window.addEventListener('pointerdown', closeFolderContextMenu, true);
    window.addEventListener('keydown', closeOnEscape, true);
    return () => {
      window.removeEventListener('pointerdown', closeFolderContextMenu, true);
      window.removeEventListener('keydown', closeOnEscape, true);
    };
  }, [folderContextMenu]);

  const toggleTriggerMode = () => {
    const current = triggerModeRef.current;
    const next: TriggerMode = current === 'edge' ? 'float' : 'edge';
    setTriggerMode(next);
    triggerModeRef.current = next;
    localStorage.setItem('drawer_trigger_mode', next);
    emitTo('edge', 'trigger-mode-changed', next).catch(() => {});
    showToast(next === 'float' ? '已切换为悬浮方块模式' : '已切换为侧边小条模式');
  };

  const toggleCanvasWorkbenchMode = () => {
    const next = !isCanvasWorkbenchMode;
    setIsCanvasWorkbenchMode(next);
    showToast(next ? '已开启画布工作台模式' : '已关闭画布工作台模式');
  };

  const toggleDrawerWorkbenchMode = () => {
    const next = !isDrawerWorkbenchMode;
    setIsDrawerWorkbenchMode(next);
    if (next) {
      if (closeTimerRef.current) {
        clearTimeout(closeTimerRef.current);
        closeTimerRef.current = null;
      }
      if (idleAutoCloseTimerRef.current) {
        clearTimeout(idleAutoCloseTimerRef.current);
        idleAutoCloseTimerRef.current = null;
      }
      isPointerInsideDrawerRef.current = true;
      isPinnedRef.current = false;
      setIsPinned(false);
      setIsOpen(true);
      setDrawerState('open');
      invoke('toggle_pin', { pinned: false }).catch(() => {});
    }
    showToast(next ? '已开启抽屉工作台模式' : '已关闭抽屉工作台模式');
  };

  const toggleAutoStartSetting = async () => {
    if (isAutoStartChanging) return;
    const previous = isAutoStart;
    const next = !isAutoStart;
    setIsAutoStartChanging(true);
    setIsAutoStart(next);
    try {
      await invoke('set_auto_start', { autoStart: next });
      const persisted = await invoke('get_auto_start');
      if (!!persisted !== next) throw new Error('autostart state verification failed');
      setIsAutoStart(!!persisted);
      showToast(next ? '已开启开机自动启动' : '已关闭开机自动启动');
    } catch (err) {
      console.error('设置开机启动失败:', err);
      setIsAutoStart(previous);
      showToast('开机启动设置失败');
    } finally {
      setIsAutoStartChanging(false);
    }
  };

  const toggleCalendarNotificationsSetting = () => {
    const next = !calendarNotificationsEnabled;
    setCalendarNotificationsEnabled(next);
    showToast(next ? '已开启日程通知' : '已关闭日程通知');
  };

  const toggleScreenshotAutoPinNoteSetting = () => {
    const next = !screenshotAutoPinNote;
    screenshotAutoPinNoteRef.current = next;
    setScreenshotAutoPinNote(next);
    showToast(next ? '截图后将自动置顶为便签' : '已关闭截图自动置顶便签');
  };

  const updateEagleImportStatus = (patch: Partial<EagleImportStatus>) => {
    setEagleImportStatus(previous => ({
      ...previous,
      ...patch,
      updatedAt: Date.now(),
    }));
  };

  const eagleApiGet = async <T,>(baseUrl: string, path: string, query?: Record<string, string | number | undefined>) => {
    const queryString = query
      ? Object.entries(query)
        .filter(([, value]) => value !== undefined && value !== '')
        .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(String(value)))
        .join('&')
      : '';
    const url = baseUrl + path + (queryString ? '?' + queryString : '');
    const response = await invoke<any>('eagle_api_get', { url });
    if (!response || typeof response !== 'object') return response as T;
    if (response.status && response.status !== 'success') {
      throw new Error(response.message || response.error || 'Eagle API 返回失败');
    }
    return ((response.data !== undefined ? response.data : response) as T);
  };

  const getEagleErrorMessage = (error: unknown) => (
    error instanceof Error ? error.message : String(error || '未知错误')
  );

  const detectEagleConnection = async (): Promise<EagleDetectionResult> => {
    let v2Error = '';
    let v1Error = '';
    let apiVersion: EagleApiVersion | undefined;
    let baseUrl = '';

    try {
      await eagleApiGet(EAGLE_API_V2_BASE_URL, '/app/info');
      apiVersion = 'v2';
      baseUrl = EAGLE_API_V2_BASE_URL;
    } catch (error) {
      v2Error = getEagleErrorMessage(error);
      try {
        await eagleApiGet(EAGLE_API_V1_BASE_URL, '/application/info');
        apiVersion = 'v1';
        baseUrl = EAGLE_API_V1_BASE_URL;
      } catch (fallbackError) {
        v1Error = getEagleErrorMessage(fallbackError);
      }
    }

    if (!apiVersion) {
      const [eagleOpen, portAccessible] = await Promise.all([
        invoke<boolean>('eagle_probe_process').catch(() => false),
        invoke<boolean>('eagle_probe_port').catch(() => false),
      ]);
      return {
        eagleOpen,
        portAccessible,
        libraryOpen: null,
        v2Error,
        v1Error,
      };
    }

    try {
      const libraryInfo = await eagleApiGet<any>(baseUrl, '/library/info');
      return {
        eagleOpen: true,
        portAccessible: true,
        libraryOpen: true,
        apiVersion,
        baseUrl,
        libraryInfo,
        v2Error: v2Error || undefined,
      };
    } catch (error) {
      return {
        eagleOpen: true,
        portAccessible: true,
        libraryOpen: false,
        apiVersion,
        baseUrl,
        v2Error: v2Error || undefined,
        libraryError: getEagleErrorMessage(error),
      };
    }
  };

  const normalizeEagleFoldersPayload = (payload: any): EagleFolderPayload[] => {
    if (Array.isArray(payload)) return payload;
    if (Array.isArray(payload?.folders)) return payload.folders;
    if (Array.isArray(payload?.data)) return payload.data;
    return [];
  };

  const normalizeEagleItemsPayload = (payload: any) => {
    const items = Array.isArray(payload)
      ? payload
      : Array.isArray(payload?.items)
        ? payload.items
        : Array.isArray(payload?.list)
          ? payload.list
          : Array.isArray(payload?.files)
            ? payload.files
            : Array.isArray(payload?.data)
              ? payload.data
              : [];
    const total = Number(payload?.total ?? payload?.count ?? 0) || 0;
    return { items: items as EagleItemPayload[], total };
  };

  const getEagleItemFolderIds = (item: EagleItemPayload) => {
    const rawFolders = item.folders ?? item.folderIds ?? item.folderId ?? item.folder ?? [];
    const values = Array.isArray(rawFolders) ? rawFolders : [rawFolders];
    return values
      .map(value => typeof value === 'object' && value ? value.id : value)
      .map(value => String(value || '').trim())
      .filter(Boolean);
  };

  const getEagleItemLocalPath = (item: EagleItemPayload, libraryPath?: string) => {
    const candidates = [
      item.filePath,
      item.path,
      item.url && /^file:/i.test(String(item.url)) ? item.url : '',
      item.metadataFilePath,
    ];
    const directPath = candidates
      .map(value => typeof value === 'string' ? normalizeLocalDragPath(value) : '')
      .find(Boolean) || '';
    if (directPath) return directPath;

    const id = String(item.id || item._id || '').trim();
    const name = String(item.name || '').trim();
    const ext = String(item.ext || item.extension || '').trim().replace(/^\./, '');
    const root = normalizeLocalDragPath(libraryPath || '').replace(/[\\/]+$/g, '');
    if (!root || !id || !name || !ext) return '';
    const separator = root.includes('\\') ? '\\' : '/';
    return `${root}${separator}images${separator}${id}.info${separator}${name}.${ext}`;
  };

  const getEagleItemThumbnailPath = (item: EagleItemPayload) => {
    const candidates = [item.thumbnailPath, item.thumbPath, item.previewPath];
    return candidates
      .map(value => typeof value === 'string' ? normalizeLocalDragPath(value) : '')
      .find(Boolean) || '';
  };

  const getEagleItemType = (item: EagleItemPayload, filePath: string): BufferItem['type'] => {
    const ext = String(item.ext || item.extension || getFileExtension(filePath || item.name || '') || '').toLowerCase().replace(/^\./, '');
    if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg', 'bmp', 'avif'].includes(ext)) return 'image';
    if (['mp4', 'mov', 'avi', 'mkv', 'webm', 'm4v'].includes(ext)) return 'video';
    return 'file';
  };

  const normalizeEagleTimestamp = (value: unknown, fallback: number) => {
    if (typeof value === 'number' && Number.isFinite(value)) {
      return value > 10_000_000_000 ? value : value * 1000;
    }
    if (typeof value === 'string' && value.trim()) {
      const parsed = Date.parse(value);
      if (Number.isFinite(parsed)) return parsed;
    }
    return fallback;
  };

  const importEagleCacheInBackground = (sourceItems: BufferItem[]) => {
    const candidates = sourceItems.filter(item => (
      (item as any).eagleSourcePath &&
      (item.type === 'image' || item.type === 'video' || item.type === 'file')
    ));
    if (candidates.length === 0) {
      updateEagleImportStatus({ phase: 'done', message: '已导入 ' + sourceItems.length + ' 个 Eagle 素材', total: sourceItems.length });
      return;
    }

    let cursor = 0;
    let cached = 0;
    let failed = 0;
    updateEagleImportStatus({
      phase: 'caching',
      message: '已导入 ' + sourceItems.length + ' 个素材，正在后台复制到缓存 0/' + candidates.length,
      total: sourceItems.length,
      imported: sourceItems.length,
      cached,
      failed,
    });

    const runNext = async () => {
      const item = candidates[cursor++];
      if (!item) return;
      try {
        const cachedPath = await invoke<string>('cache_local_file_to_dir', {
          path: (item as any).eagleSourcePath,
          dir: (await getLatestFileCacheDir()) || undefined,
        });
        if (!cachedPath) throw new Error('未返回缓存路径');
        const cachedItem = {
          ...item,
          path: cachedPath,
          url: convertFileSrc(cachedPath),
          sourceUrl: (item as any).eagleSourceUrl || item.sourceUrl,
          originalUrl: (item as any).eagleSourceUrl || item.originalUrl,
          eagleSourcePath: undefined,
          eagleThumbnailPath: undefined,
        } as BufferItem;
        setItems(prev => prev.map(current => current.id === item.id ? cachedItem : current));
        ensureMediaThumbnail(cachedItem);
        cached += 1;
      } catch (err) {
        console.warn('Eagle 素材后台缓存失败:', err);
        failed += 1;
      } finally {
        const done = cursor >= candidates.length;
        updateEagleImportStatus({
          phase: done ? 'done' : 'caching',
          message: done
            ? 'Eagle 导入完成：' + sourceItems.length + ' 个素材，缓存 ' + cached + ' 个' + (failed ? '，失败 ' + failed + ' 个' : '')
            : '已导入 ' + sourceItems.length + ' 个素材，正在后台复制到缓存 ' + Math.min(cursor, candidates.length) + '/' + candidates.length,
          total: sourceItems.length,
          imported: sourceItems.length,
          cached,
          failed,
        });
        if (!done) await runNext();
      }
    };

    Array.from({ length: Math.min(EAGLE_IMPORT_CACHE_CONCURRENCY, candidates.length) }).forEach(() => {
      void runNext();
    });
  };

  const applyEagleImportRecords = async (options: {
    folders: EagleFolderPayload[];
    entries: EagleItemPayload[];
    libraryInfo?: any;
    startedAt: number;
    total?: number;
    sourceLabel: string;
  }) => {
    const { folders: eagleFolders, entries, libraryInfo, startedAt, sourceLabel } = options;
    const existingFolderKeys = new Set(foldersRef.current.map(folder => (folder.parentId || '') + '|' + folder.name.trim().toLowerCase()));
    const folderIdMap = new Map<string, string>();
    const nextFolders: Folder[] = [];
    const makeFolderId = createAssetId;
    const pushEagleFolder = (folder: EagleFolderPayload, parentId?: string) => {
      const name = String(folder.name || 'Eagle 文件夹').trim() || 'Eagle 文件夹';
      const key = (parentId || '') + '|' + name.toLowerCase();
      const existing = foldersRef.current.find(item => (item.parentId || '') === (parentId || '') && item.name.trim().toLowerCase() === name.toLowerCase())
        || nextFolders.find(item => (item.parentId || '') === (parentId || '') && item.name.trim().toLowerCase() === name.toLowerCase());
      const id = existing?.id || makeFolderId();
      if (!existing && !existingFolderKeys.has(key)) {
        nextFolders.push({ id, name, color: '#f59e0b', parentId });
        existingFolderKeys.add(key);
      }
      if (folder.id) folderIdMap.set(String(folder.id), id);
      if (Array.isArray(folder.children)) folder.children.forEach(child => pushEagleFolder(child, id));
    };
    eagleFolders.forEach(folder => pushEagleFolder(folder));

    const existingEagleIds = new Set(itemsRef.current.map(item => String((item as any).eagleId || '')).filter(Boolean));
    const existingPaths = new Set(itemsRef.current.map(item => normalizeLocalDragPath(item.path || '')).filter(Boolean));
    const nextItems: BufferItem[] = [];
    const libraryPath = String(libraryInfo?.path || '').trim();

    entries.forEach((entry, index) => {
      const eagleId = String(entry.id || entry._id || '').trim();
      if (eagleId && existingEagleIds.has(eagleId)) return;
      const filePath = getEagleItemLocalPath(entry, libraryPath);
      if (!filePath) return;
      const normalizedPath = normalizeLocalDragPath(filePath);
      if (normalizedPath && existingPaths.has(normalizedPath)) return;

      const thumbnailPath = getEagleItemThumbnailPath(entry);
      const folderIds = getEagleItemFolderIds(entry);
      const folderId = folderIds.map(id => folderIdMap.get(id)).find(Boolean);
      const name = String(entry.name || normalizedPath.split(/[\\/]/).pop() || 'Eagle 素材 ' + (index + 1)).trim();
      const tags = Array.isArray(entry.tags) ? entry.tags.map((tag: unknown) => String(tag || '').trim()).filter(Boolean) : [];
      const remarkParts = [
        entry.annotation,
        tags.length > 0 ? '#' + tags.join(' #') : '',
        entry.url ? '来源：' + entry.url : '',
      ].filter(value => typeof value === 'string' && value.trim());
      const type = getEagleItemType(entry, normalizedPath);
      const sourceUrl = typeof entry.url === 'string' && /^https?:\/\//i.test(entry.url) ? entry.url : undefined;
      const item = {
        id: createAssetId(),
        type,
        content: name,
        name,
        path: normalizedPath,
        url: convertFileSrc(normalizedPath),
        thumbnail: thumbnailPath ? convertFileSrc(thumbnailPath) : undefined,
        sourceUrl,
        originalUrl: sourceUrl,
        remark: remarkParts.join('\n') || undefined,
        remarks: remarkParts.length > 0 ? remarkParts : undefined,
        folderId,
        createdAt: normalizeEagleTimestamp(entry.importedAt || entry.createdAt || entry.modificationTime || entry.modifiedAt, startedAt + nextItems.length),
        isQuickAccess: false,
        eagleId: eagleId || undefined,
        eagleSourcePath: normalizedPath,
        eagleSourceUrl: sourceUrl || (typeof entry.url === 'string' ? entry.url : undefined),
        eagleThumbnailPath: thumbnailPath || undefined,
      } as BufferItem;
      nextItems.push(item);
      if (eagleId) existingEagleIds.add(eagleId);
      if (normalizedPath) existingPaths.add(normalizedPath);
    });

    const total = options.total || entries.length;
    if (nextItems.length === 0 && nextFolders.length === 0) {
      updateEagleImportStatus({ phase: 'done', message: sourceLabel + ' 没有新的可导入素材', total, imported: 0 });
      showToast(sourceLabel + ' 没有新的可导入素材');
      return 0;
    }

    pushDrawerUndoSnapshot('从 ' + sourceLabel + ' 导入');
    if (nextFolders.length > 0) setFolders(prev => {
      const mergedFolders = normalizeDrawerFolders([...prev, ...nextFolders]);
      persistFoldersSnapshot(mergedFolders);
      return mergedFolders;
    });
    if (nextItems.length > 0) {
      setItems(prev => [...nextItems, ...prev]);
      nextItems.slice(0, 24).forEach(ensureMediaThumbnail);
    }
    setActiveTab('all');
    const firstFolderId = nextItems.find(item => item.folderId)?.folderId || nextFolders[0]?.id;
    if (firstFolderId) setActiveFolderId(firstFolderId);
    showToast('已从 ' + sourceLabel + ' 导入 ' + nextItems.length + ' 个素材');
    updateEagleImportStatus({
      phase: 'importing',
      message: '已导入 ' + nextItems.length + ' 个素材，准备后台复制缓存...',
      total,
      imported: nextItems.length,
    });
    importEagleCacheInBackground(nextItems);
    return nextItems.length;
  };

  const importFromEagle = async () => {
    if (['checking', 'reading', 'importing', 'caching'].includes(eagleImportStatus.phase)) return;
    const startedAt = Date.now();
    setEagleImportStatus({
      phase: 'checking',
      message: '正在连接 Eagle 本地服务...',
      total: 0,
      imported: 0,
      cached: 0,
      failed: 0,
      startedAt,
      updatedAt: startedAt,
      diagnostics: undefined,
    });

    try {
      const detection = await detectEagleConnection();
      if (!detection.apiVersion || !detection.baseUrl) {
        updateEagleImportStatus({
          phase: 'error',
          message: '未检测到可用的 Eagle 本地 API，可改用 .library 离线导入',
          diagnostics: detection,
        });
        showToast('Eagle 连接检测失败，请查看诊断或选择 .library 离线导入');
        return;
      }
      if (!detection.libraryOpen) {
        updateEagleImportStatus({
          phase: 'error',
          message: 'Eagle 已打开，但当前没有可读取的资料库',
          diagnostics: detection,
        });
        showToast('请先在 Eagle 中打开资料库，或选择 .library 离线导入');
        return;
      }

      updateEagleImportStatus({
        phase: 'reading',
        message: '已连接 Eagle ' + detection.apiVersion.toUpperCase() + '，正在读取素材库...',
        diagnostics: detection,
      });
      const libraryInfo = detection.libraryInfo;
      const folderPayload = await eagleApiGet<any>(
        detection.baseUrl,
        detection.apiVersion === 'v2' ? '/folder/get' : '/folder/list',
      );

      const eagleFolders = normalizeEagleFoldersPayload(folderPayload);
      const existingFolderKeys = new Set(foldersRef.current.map(folder => (folder.parentId || '') + '|' + folder.name.trim().toLowerCase()));
      const folderIdMap = new Map<string, string>();
      const nextFolders: Folder[] = [];
      const makeFolderId = createAssetId;
      const pushEagleFolder = (folder: EagleFolderPayload, parentId?: string) => {
        const name = String(folder.name || 'Eagle 文件夹').trim() || 'Eagle 文件夹';
        const key = (parentId || '') + '|' + name.toLowerCase();
        const existing = foldersRef.current.find(item => (item.parentId || '') === (parentId || '') && item.name.trim().toLowerCase() === name.toLowerCase())
          || nextFolders.find(item => (item.parentId || '') === (parentId || '') && item.name.trim().toLowerCase() === name.toLowerCase());
        const id = existing?.id || makeFolderId();
        if (!existing && !existingFolderKeys.has(key)) {
          nextFolders.push({ id, name, color: '#f59e0b', parentId });
          existingFolderKeys.add(key);
        }
        if (folder.id) folderIdMap.set(String(folder.id), id);
        if (Array.isArray(folder.children)) {
          folder.children.forEach(child => pushEagleFolder(child, id));
        }
      };
      eagleFolders.forEach(folder => pushEagleFolder(folder));

      const existingEagleIds = new Set(itemsRef.current.map(item => String((item as any).eagleId || '')).filter(Boolean));
      const existingPaths = new Set(itemsRef.current.map(item => normalizeLocalDragPath(item.path || '')).filter(Boolean));
      const nextItems: BufferItem[] = [];
      let offset = 0;
      let total = 0;

      while (true) {
        updateEagleImportStatus({
          phase: 'reading',
          message: '正在读取 Eagle 素材 ' + offset + (total ? '/' + total : '') + '...',
          total,
          imported: nextItems.length,
        });
        const payload = await eagleApiGet<any>(
          detection.baseUrl,
          detection.apiVersion === 'v2' ? '/item/get' : '/item/list',
          { limit: EAGLE_IMPORT_PAGE_LIMIT, offset },
        );
        const { items: eagleItems, total: pageTotal } = normalizeEagleItemsPayload(payload);
        if (pageTotal > 0) total = pageTotal;
        if (eagleItems.length === 0) break;

        eagleItems.forEach((entry, index) => {
          const eagleId = String(entry.id || entry._id || '').trim();
          if (eagleId && existingEagleIds.has(eagleId)) return;
          const filePath = getEagleItemLocalPath(entry, libraryInfo?.path);
          if (!filePath) return;
          const normalizedPath = normalizeLocalDragPath(filePath);
          if (normalizedPath && existingPaths.has(normalizedPath)) return;

          const thumbnailPath = getEagleItemThumbnailPath(entry);
          const folderIds = getEagleItemFolderIds(entry);
          const folderId = folderIds.map(id => folderIdMap.get(id)).find(Boolean);
          const name = String(entry.name || normalizedPath.split(/[\\/]/).pop() || 'Eagle 素材 ' + (offset + index + 1)).trim();
          const tags = Array.isArray(entry.tags) ? entry.tags.map((tag: unknown) => String(tag || '').trim()).filter(Boolean) : [];
          const remarkParts = [
            entry.annotation,
            tags.length > 0 ? '#' + tags.join(' #') : '',
            entry.url ? '来源：' + entry.url : '',
          ].filter(value => typeof value === 'string' && value.trim());
          const type = getEagleItemType(entry, normalizedPath);
          const sourceUrl = typeof entry.url === 'string' && /^https?:\/\//i.test(entry.url) ? entry.url : undefined;
          const item = {
            id: createAssetId(),
            type,
            content: name,
            name,
            path: normalizedPath,
            url: convertFileSrc(normalizedPath),
            thumbnail: thumbnailPath ? convertFileSrc(thumbnailPath) : undefined,
            sourceUrl,
            originalUrl: sourceUrl,
            remark: remarkParts.join('\n') || undefined,
            remarks: remarkParts.length > 0 ? remarkParts : undefined,
            folderId,
            createdAt: normalizeEagleTimestamp(entry.importedAt || entry.createdAt || entry.modifiedAt, startedAt + nextItems.length),
            isQuickAccess: false,
            eagleId: eagleId || undefined,
            eagleSourcePath: normalizedPath,
            eagleSourceUrl: sourceUrl || (typeof entry.url === 'string' ? entry.url : undefined),
            eagleThumbnailPath: thumbnailPath || undefined,
          } as BufferItem;
          nextItems.push(item);
          if (eagleId) existingEagleIds.add(eagleId);
          if (normalizedPath) existingPaths.add(normalizedPath);
        });

        offset += eagleItems.length;
        if (eagleItems.length < EAGLE_IMPORT_PAGE_LIMIT) break;
        if (total > 0 && offset >= total) break;
      }

      if (nextItems.length === 0 && nextFolders.length === 0) {
        updateEagleImportStatus({ phase: 'done', message: 'Eagle 没有新的可导入素材', total, imported: 0 });
        showToast('Eagle 没有新的可导入素材');
        return;
      }

      pushDrawerUndoSnapshot('从 Eagle 导入');
      if (nextFolders.length > 0) setFolders(prev => {
        const mergedFolders = normalizeDrawerFolders([...prev, ...nextFolders]);
        persistFoldersSnapshot(mergedFolders);
        return mergedFolders;
      });
      if (nextItems.length > 0) {
        setItems(prev => [...nextItems, ...prev]);
        nextItems.slice(0, 24).forEach(ensureMediaThumbnail);
      }
      setActiveTab('all');
      const firstFolderId = nextItems.find(item => item.folderId)?.folderId || nextFolders[0]?.id;
      if (firstFolderId) setActiveFolderId(firstFolderId);
      showToast('已从 Eagle 导入 ' + nextItems.length + ' 个素材');
      updateEagleImportStatus({
        phase: 'importing',
        message: '已导入 ' + nextItems.length + ' 个素材，准备后台复制缓存...',
        total: total || nextItems.length,
        imported: nextItems.length,
      });
      importEagleCacheInBackground(nextItems);
      if (libraryInfo?.name) console.info('Eagle library imported:', libraryInfo.name);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err || '未知错误');
      console.warn('Eagle 导入失败:', err);
      updateEagleImportStatus({
        phase: 'error',
        message: 'Eagle 导入失败：' + message,
      });
      showToast('Eagle 导入失败，请查看诊断或选择 .library 离线导入');
    }
  };

  const importFromEagleLibrary = async () => {
    if (['checking', 'reading', 'importing', 'caching'].includes(eagleImportStatus.phase)) return;
    try {
      const selected = await open({
        directory: true,
        multiple: false,
        title: '选择 Eagle .library 资料库目录',
      });
      if (typeof selected !== 'string' || !selected) return;
      if (!/\.library[\\/]?$/i.test(selected)) {
        showToast('请选择以 .library 结尾的 Eagle 资料库目录');
        return;
      }

      const startedAt = Date.now();
      setEagleImportStatus({
        phase: 'reading',
        message: '正在只读扫描 Eagle 离线资料库...',
        total: 0,
        imported: 0,
        cached: 0,
        failed: 0,
        startedAt,
        updatedAt: startedAt,
      });
      const payload = await invoke<EagleOfflineLibraryPayload>('eagle_read_offline_library', { path: selected });
      const entries = Array.isArray(payload.items) ? payload.items : [];
      const eagleFolders = normalizeEagleFoldersPayload(payload.folders || []);
      updateEagleImportStatus({
        phase: 'importing',
        message: '已扫描 ' + entries.length + ' 个离线素材，正在导入...',
        total: entries.length,
      });
      await applyEagleImportRecords({
        folders: eagleFolders,
        entries,
        libraryInfo: payload.library,
        startedAt,
        total: entries.length,
        sourceLabel: payload.library?.name ? 'Eagle 离线库「' + payload.library.name + '」' : 'Eagle 离线库',
      });
    } catch (error) {
      const message = getEagleErrorMessage(error);
      console.warn('Eagle 离线导入失败:', error);
      updateEagleImportStatus({
        phase: 'error',
        message: 'Eagle 离线导入失败：' + message,
      });
      showToast('Eagle 离线导入失败：' + message);
    }
  };

  useEffect(() => {
    let unlistenTrayTrigger: (() => void) | undefined;
    let unlistenTrayTheme: (() => void) | undefined;

    listen('tray-toggle-trigger-mode', () => {
      if (stateRef.current.isAntiTouchMode) {
        enforceAntiTouchClosed(true);
        return;
      }
      toggleTriggerMode();
    }).then(f => unlistenTrayTrigger = f);

    listen('tray-toggle-theme', () => {
      setIsDark(prev => {
        const next = !prev;
        localStorage.setItem('theme', next ? 'dark' : 'light');
        emitTo('edge', 'theme-changed', next ? 'dark' : 'light').catch(() => {});
        showToast(next ? '已切换为深色主题' : '已切换为浅色主题');
        return next;
      });
    }).then(f => unlistenTrayTheme = f);

    return () => {
      if (unlistenTrayTrigger) unlistenTrayTrigger();
      if (unlistenTrayTheme) unlistenTrayTheme();
    };
  }, [triggerMode]);

  const folderChildrenByParent = useMemo(() => {
    const grouped = new Map<string, Folder[]>();
    folders.forEach(folder => {
      if (!folder.parentId) return;
      grouped.set(folder.parentId, [...(grouped.get(folder.parentId) || []), folder]);
    });
    return grouped;
  }, [folders]);
  const visibleFolderEntries = useMemo(() => flattenDrawerFolderTree(folders, collapsedFolderIds), [folders, collapsedFolderIds]);
  const orderedFolderEntries = useMemo(() => flattenDrawerFolderTree(folders, []), [folders]);
  const orderedFolders = useMemo(() => orderedFolderEntries.map(entry => entry.folder), [orderedFolderEntries]);
  const visibleFolderRailEntryCount = useMemo(() => (
    visibleFolderEntries.length
  ), [visibleFolderEntries]);
  const aiGeneratedImageFolderIds = useMemo(
    () => getAiGeneratedImageFolderIds(folders),
    [folders],
  );
  const folderItemCounts = useMemo(() => {
    const directCounts = new Map(
      folderAssetCountRows
        .filter((row): row is { folderId: string; count: number } => Boolean(row.folderId))
        .map(row => [row.folderId, row.count]),
    );
    const counts = new Map<string, number>();
    folders.forEach(folder => {
      const scopeIds = getDrawerFolderScopeIds(folders, folder.id);
      let count = 0;
      scopeIds.forEach(id => { count += directCounts.get(id) || 0; });
      counts.set(folder.id, count);
    });
    return counts;
  }, [folderAssetCountRows, folders]);
  const visibleFolderIds = useMemo(() => visibleFolderEntries.map(entry => entry.folder.id), [visibleFolderEntries]);
  const folderMoveSelectionIds = useMemo(() => (
    selectedFolderIds.filter(id => folders.some(folder => folder.id === id))
  ), [folders, selectedFolderIds]);
  const folderMoveTargetEntries = orderedFolderEntries;
  const isInvalidFolderMoveTarget = useCallback((targetId: string | null, movingIds = folderMoveSelectionIds) => {
    if (!targetId) return false;
    if (movingIds.includes(targetId)) return true;
    return movingIds.some(id => isDrawerFolderDescendant(folders, targetId, id));
  }, [folderMoveSelectionIds, folders]);
  const mainDrawerItemCount = useMemo(() => (
    folderAssetCountRows.find(row => row.folderId === null)?.count || 0
  ), [folderAssetCountRows]);
  const drawerAiAnalysisSummary = useMemo(() => {
    if (assetStorageMode === 'sqlite' && sqliteAiAnalysisSummary) {
      return sqliteAiAnalysisSummary;
    }
    const images = items.filter(item => item.type === 'image');
    return {
      analyzed: images.filter(item => hasUsableInspirationAiTags(item.inspirationProfile)).length,
      skipped: images.filter(item => (
        !hasUsableInspirationAiTags(item.inspirationProfile)
        && shouldSkipInspirationAnalysis(item.inspirationAnalysisFailure)
      )).length,
      waitingRetry: images.filter(item => (
        !hasUsableInspirationAiTags(item.inspirationProfile)
        && Boolean(item.inspirationAnalysisFailure)
        && !shouldSkipInspirationAnalysis(item.inspirationAnalysisFailure)
      )).length,
      total: images.length,
    };
  }, [assetStorageMode, items, sqliteAiAnalysisSummary]);
  const normalizedDeferredSearchQuery = useMemo(
    () => deferredSearchQuery.trim().toLowerCase(),
    [deferredSearchQuery],
  );
  const drawerItemSearchTextCacheRef = useRef(new WeakMap<BufferItem, string>());
  const drawerSearchIndex = useMemo(() => {
    if (assetStorageMode !== 'json' || !isSearchActive) return [] as Array<{ item: BufferItem; text: string }>;
    const cache = drawerItemSearchTextCacheRef.current;
    return items.map(item => {
      let text = cache.get(item);
      if (text === undefined) {
        text = getDrawerItemSearchText(item);
        cache.set(item, text);
      }
      return { item, text };
    });
  }, [assetStorageMode, isSearchActive, items]);
  const drawerFolderScopeIds = useMemo(() => (
    activeFolderId === 'all'
      ? []
      : [...getDrawerFolderScopeIds(folders, activeFolderId)].sort()
  ), [activeFolderId, folders]);
  const drawerAssetListOptions = useMemo<AssetListOptions>(() => {
    const keyword = isSearchActive ? deferredSearchQuery.trim() : '';
    return {
      keyword: keyword || undefined,
      folder_id: !keyword && activeFolderId === 'all' ? 'all' : undefined,
      folder_ids: !keyword && activeFolderId !== 'all' ? drawerFolderScopeIds : undefined,
      file_type: activeTab !== 'all' && activeTab !== 'notes' && activeTab !== 'calendar'
        ? activeTab
        : undefined,
      sort: 'created_at_desc',
    };
  }, [activeFolderId, activeTab, deferredSearchQuery, drawerFolderScopeIds, isSearchActive]);
  const drawerAssetQueryKey = useMemo(
    () => JSON.stringify(drawerAssetListOptions),
    [drawerAssetListOptions],
  );
  useEffect(() => {
    drawerUndoStackRef.current = [];
    drawerTextEditUndoIdsRef.current.clear();
    assetWindowOffsetRef.current = 0;
    setAssetWindowOffset(0);
  }, [drawerAssetQueryKey]);
  const isUtilityActiveTab = activeTab === 'notes' || activeTab === 'calendar' || isCanvasMode;
  const assetMatchesDrawerQuery = useCallback((item: BufferItem, options: AssetListOptions) => {
    if (options.file_type && item.type !== options.file_type) return false;
    const keyword = options.keyword?.trim().toLowerCase();
    if (keyword && !getDrawerItemSearchText(item).includes(keyword)) return false;
    if (!keyword && options.folder_ids && options.folder_ids.length > 0) {
      return Boolean(item.folderId && options.folder_ids.includes(item.folderId));
    }
    if (!keyword && options.folder_id === 'all') return !item.folderId;
    if (!keyword && options.folder_id) return item.folderId === options.folder_id;
    return true;
  }, []);

  useEffect(() => {
    if (!assetLibraryReady || assetStorageMode !== 'sqlite' || isUtilityActiveTab) {
      assetQueryRequestIdRef.current += 1;
      assetPageOffsetsInFlightRef.current.clear();
      setIsAssetPageLoading(false);
      return;
    }
    const requestId = ++assetQueryRequestIdRef.current;
    const startedAt = performance.now();
    assetPageOffsetsInFlightRef.current.clear();
    assetPageOffsetsInFlightRef.current.add(0);
    assetQueryOptionsRef.current = drawerAssetListOptions;
    setIsAssetPageLoading(true);

    void Promise.all([
      getAssetCount(drawerAssetListOptions),
      listAssets({ ...drawerAssetListOptions, offset: 0, limit: ASSET_PAGE_SIZE }),
    ]).then(([count, firstPage]) => {
      if (requestId !== assetQueryRequestIdRef.current) return;
      const compactPage = firstPage.map(stripHeavyDataThumbnail);
      replaceAssetsFromQuery(compactPage);
      assetWindowOffsetRef.current = 0;
      setAssetWindowOffset(0);
      assetQueryTotalCountRef.current = count;
      setTotalAssetCount(count);
      setHasMoreAssets(compactPage.length < count);
      if (import.meta.env.DEV) {
        console.debug('[DrawerPerf] initial query', {
          milliseconds: Math.round((performance.now() - startedAt) * 10) / 10,
          assetsLoaded: compactPage.length,
          totalAssets: count,
        });
      }
    }).catch(error => {
      if (requestId === assetQueryRequestIdRef.current) {
        console.warn('SQLite 素材首屏查询失败:', error);
        replaceAssetsFromQuery([]);
        setTotalAssetCount(0);
        setHasMoreAssets(false);
      }
    }).finally(() => {
      assetPageOffsetsInFlightRef.current.delete(0);
      if (requestId === assetQueryRequestIdRef.current) {
        setIsAssetPageLoading(false);
        setIsDataLoaded(true);
      }
    });
  }, [
    assetLibraryReady,
    assetStorageMode,
    drawerAssetListOptions,
    drawerAssetQueryKey,
    isUtilityActiveTab,
    replaceAssetsFromQuery,
  ]);

  const loadNextDrawerAssetPage = useCallback(() => {
    if (assetStorageMode !== 'sqlite' || isAssetPageLoading || !hasMoreAssets) return;
    const requestId = assetQueryRequestIdRef.current;
    const cachedQueryAssets = itemsRef.current.filter(item => (
      assetMatchesDrawerQuery(item, assetQueryOptionsRef.current)
    ));
    const offset = assetWindowOffsetRef.current + cachedQueryAssets.length;
    if (assetPageOffsetsInFlightRef.current.has(offset)) return;
    assetPageOffsetsInFlightRef.current.add(offset);
    setIsAssetPageLoading(true);
    const startedAt = performance.now();
    void listAssets({ ...assetQueryOptionsRef.current, offset, limit: ASSET_PAGE_SIZE })
      .then(page => {
        if (requestId !== assetQueryRequestIdRef.current) return;
        const compactPage = page.map(stripHeavyDataThumbnail);
        const merged = mergeDrawerAssetPageWindow(
          cachedQueryAssets,
          compactPage,
          MAX_DRAWER_ASSET_CACHE_SIZE,
        );
        if (merged.evictedFromStart > 0) {
          const nextWindowOffset = assetWindowOffsetRef.current + merged.evictedFromStart;
          assetWindowOffsetRef.current = nextWindowOffset;
          setAssetWindowOffset(nextWindowOffset);
          replaceAssetsFromQuery(merged.assets);
        } else {
          appendAssetsFromQuery(compactPage);
        }
        setHasMoreAssets(
          compactPage.length > 0
          && offset + compactPage.length < assetQueryTotalCountRef.current,
        );
        if (import.meta.env.DEV) {
          console.debug('[DrawerPerf] next page', {
            offset,
            milliseconds: Math.round((performance.now() - startedAt) * 10) / 10,
            assetsLoaded: compactPage.length,
          });
        }
      })
      .catch(error => console.warn('SQLite 素材分页查询失败:', error))
      .finally(() => {
        assetPageOffsetsInFlightRef.current.delete(offset);
        if (requestId === assetQueryRequestIdRef.current) setIsAssetPageLoading(false);
      });
  }, [
    appendAssetsFromQuery,
    assetMatchesDrawerQuery,
    assetStorageMode,
    hasMoreAssets,
    isAssetPageLoading,
    replaceAssetsFromQuery,
  ]);

  const loadPreviousDrawerAssetPage = useCallback(() => {
    if (assetStorageMode !== 'sqlite' || isAssetPageLoading || assetWindowOffsetRef.current <= 0) return;
    const requestId = assetQueryRequestIdRef.current;
    const currentWindowOffset = assetWindowOffsetRef.current;
    const limit = Math.min(ASSET_PAGE_SIZE, currentWindowOffset);
    const offset = currentWindowOffset - limit;
    if (assetPageOffsetsInFlightRef.current.has(offset)) return;
    assetPageOffsetsInFlightRef.current.add(offset);
    setIsAssetPageLoading(true);
    const startedAt = performance.now();
    void listAssets({ ...assetQueryOptionsRef.current, offset, limit })
      .then(page => {
        if (requestId !== assetQueryRequestIdRef.current) return;
        const compactPage = page.map(stripHeavyDataThumbnail);
        const cachedQueryAssets = itemsRef.current.filter(item => (
          assetMatchesDrawerQuery(item, assetQueryOptionsRef.current)
        ));
        const merged = [...new Map([...compactPage, ...cachedQueryAssets]
          .map(item => [item.id, item])).values()]
          .slice(0, MAX_DRAWER_ASSET_CACHE_SIZE);
        assetWindowOffsetRef.current = offset;
        setAssetWindowOffset(offset);
        replaceAssetsFromQuery(merged);
        setHasMoreAssets(offset + merged.length < assetQueryTotalCountRef.current);
        if (import.meta.env.DEV) {
          console.debug('[DrawerPerf] previous page', {
            offset,
            milliseconds: Math.round((performance.now() - startedAt) * 10) / 10,
            assetsLoaded: compactPage.length,
          });
        }
      })
      .catch(error => console.warn('SQLite 素材上一页查询失败:', error))
      .finally(() => {
        assetPageOffsetsInFlightRef.current.delete(offset);
        if (requestId === assetQueryRequestIdRef.current) setIsAssetPageLoading(false);
      });
  }, [
    assetMatchesDrawerQuery,
    assetStorageMode,
    isAssetPageLoading,
    replaceAssetsFromQuery,
  ]);

  useEffect(() => {
    if (!assetLibraryReady || assetStorageMode !== 'sqlite') return;
    let cancelled = false;
    void Promise.all([
      getFolderAssetCounts(DEFAULT_LIBRARY_ID),
      listAssets({ quick_access: true, sort: 'updated_at_desc', offset: 0, limit: ASSET_PAGE_SIZE }),
      getAssetCount(assetQueryOptionsRef.current),
    ]).then(([counts, pinned, currentQueryCount]) => {
      if (cancelled) return;
      setFolderAssetCountRows(counts);
      setQuickAccessItems(pinned.map(stripHeavyDataThumbnail));
      assetQueryTotalCountRef.current = currentQueryCount;
      setTotalAssetCount(currentQueryCount);
      const loadedQueryCount = itemsRef.current.filter(item => (
        assetMatchesDrawerQuery(item, assetQueryOptionsRef.current)
      )).length;
      setHasMoreAssets(assetWindowOffsetRef.current + loadedQueryCount < currentQueryCount);
    }).catch(error => console.warn('SQLite 素材统计查询失败:', error));
    return () => { cancelled = true; };
  }, [assetLibraryReady, assetMatchesDrawerQuery, assetStatsRevision, assetStorageMode]);

  useEffect(() => {
    if (assetStorageMode !== 'json') return;
    setQuickAccessItems(items.filter(item => item.isQuickAccess));
    const counts = new Map<string | null, number>();
    items.forEach(item => {
      const folderId = item.folderId || null;
      counts.set(folderId, (counts.get(folderId) || 0) + 1);
    });
    setFolderAssetCountRows([...counts].map(([folderId, count]) => ({ folderId, count })));
  }, [assetStorageMode, items]);

  const drawerScopedItems = useMemo(() => {
    if (isCanvasMode) return [];
    if (assetStorageMode === 'sqlite') {
      if (activeTab === 'notes' || activeTab === 'calendar') return [];
      let result = items;
      if (normalizedDeferredSearchQuery) {
        result = result.filter(item => getDrawerItemSearchText(item).includes(normalizedDeferredSearchQuery));
      } else if (activeFolderId === 'all') {
        result = result.filter(item => !item.folderId);
      } else {
        const scopeIds = new Set(drawerFolderScopeIds);
        result = result.filter(item => Boolean(item.folderId && scopeIds.has(item.folderId)));
      }
      return activeTab === 'all' ? result : result.filter(item => item.type === activeTab);
    }
    let result = items;
    const hasSearchQuery = Boolean(normalizedDeferredSearchQuery);
    if (hasSearchQuery) {
      result = drawerSearchIndex
        .filter(entry => entry.text.includes(normalizedDeferredSearchQuery))
        .map(entry => entry.item);
    }
    if (!hasSearchQuery) {
      if (activeFolderId === 'all') {
        result = result.filter(item => !item.folderId);
      } else {
        const folderScopeIds = getDrawerFolderScopeIds(folders, activeFolderId);
        result = result.filter(item => !!item.folderId && folderScopeIds.has(item.folderId));
      }
    }
    if (activeTab === 'notes' || activeTab === 'calendar') {
      return [];
    }
    return result.filter(item => activeTab === 'all' || item.type === activeTab);
  }, [
    activeFolderId,
    activeTab,
    assetStorageMode,
    drawerSearchIndex,
    drawerFolderScopeIds,
    folders,
    isCanvasMode,
    items,
    normalizedDeferredSearchQuery,
  ]);
  const drawerAiClassificationGroups = useMemo(() => (
    buildAiClassificationGroups(drawerScopedItems, drawerAiClassificationDimension)
  ), [drawerAiClassificationDimension, drawerScopedItems]);
  const displayItems = useMemo(() => {
    if (!isDrawerAiClassificationMode || activeDrawerAiClassificationLabel === 'all') {
      return drawerScopedItems;
    }
    return drawerScopedItems.filter(item => itemMatchesAiClassification(
      item,
      drawerAiClassificationDimension,
      activeDrawerAiClassificationLabel,
    ));
  }, [
    activeDrawerAiClassificationLabel,
    drawerAiClassificationDimension,
    drawerScopedItems,
    isDrawerAiClassificationMode,
  ]);
  useEffect(() => {
    if (!isDrawerAiClassificationMode) {
      setActiveDrawerAiClassificationLabel('all');
      return;
    }
    if (
      activeDrawerAiClassificationLabel !== 'all'
      && !drawerAiClassificationGroups.some(group => group.label === activeDrawerAiClassificationLabel)
    ) {
      setActiveDrawerAiClassificationLabel('all');
    }
  }, [
    activeDrawerAiClassificationLabel,
    drawerAiClassificationGroups,
    isDrawerAiClassificationMode,
  ]);
  const [canvasSearchMediaResults, setCanvasSearchMediaResults] = useState({
    candidates: [] as BufferItem[],
    total: 0,
  });
  useEffect(() => {
    const query = normalizedDeferredSearchQuery;
    if (!isCanvasMode || !isSearchActive || !query || assetStorageMode !== 'sqlite') {
      setCanvasSearchMediaResults({ candidates: [], total: 0 });
      return;
    }
    let cancelled = false;
    const limit = Math.max(1, canvasSearchCandidateLimit);
    void Promise.all([
      listAssets({ keyword: query, file_type: 'image', sort: 'created_at_desc', limit }),
      listAssets({ keyword: query, file_type: 'video', sort: 'created_at_desc', limit }),
      getAssetCount({ keyword: query, file_type: 'image' }),
      getAssetCount({ keyword: query, file_type: 'video' }),
    ]).then(([images, videos, imageCount, videoCount]) => {
      if (cancelled) return;
      const candidates = [...images, ...videos]
        .filter(isCanvasDrawerMediaItem)
        .sort((left, right) => right.createdAt - left.createdAt)
        .slice(0, limit)
        .map(stripHeavyDataThumbnail);
      setCanvasSearchMediaResults({ candidates, total: imageCount + videoCount });
    }).catch(error => console.warn('SQLite 画布素材搜索失败:', error));
    return () => { cancelled = true; };
  }, [
    assetStorageMode,
    canvasSearchCandidateLimit,
    isCanvasMode,
    isSearchActive,
    normalizedDeferredSearchQuery,
  ]);
  const canvasDrawerSourceItemIds = useMemo(() => {
    if (!isCanvasMode || !isSearchActive || !normalizedDeferredSearchQuery) return new Set<string>();
    return new Set(canvasItems.flatMap(canvasItem => (
      canvasItem.item.sourceItemId ? [canvasItem.item.sourceItemId] : []
    )));
  }, [canvasItems, isCanvasMode, isSearchActive, normalizedDeferredSearchQuery]);

  const setDrawerItemQuickAccess = useCallback((item: BufferItem, enabled: boolean) => {
    const nextItem = { ...item, isQuickAccess: enabled };
    const isLoaded = itemsRef.current.some(candidate => candidate.id === item.id);
    if (isLoaded) {
      setItems(previous => previous.map(candidate => candidate.id === item.id ? nextItem : candidate));
    } else if (assetStorageMode === 'sqlite') {
      void updateAsset(item.id, { metadata: nextItem })
        .then(() => setAssetStatsRevision(revision => revision + 1))
        .catch(error => console.warn('更新快速访问失败:', error));
    }
    setQuickAccessItems(previous => enabled
      ? [...new Map([nextItem, ...previous].map(candidate => [candidate.id, candidate])).values()]
      : previous.filter(candidate => candidate.id !== item.id));
  }, [assetStorageMode, setItems]);

  const drawerCardActionContext = useMemo(() => ({}), []);

  const calendarEvents = useMemo<CalendarScheduleEvent[]>(() => {
    const sourceById = new Map(items.map(item => [item.id, item]));

    return openFloatingNoteEntries.flatMap(({ label, snapshot }) => {
      if (!snapshot || snapshot.type !== 'text' || snapshot.noteMode !== 'schedule' || !Array.isArray(snapshot.scheduleItems)) {
        return [];
      }

      const source = sourceById.get(snapshot.itemId);
      const fallbackTagIds = getFolderTagIds(snapshot.folderId || source?.folderId, snapshot.tagIds);
      const sourceTitle = snapshot.name || source?.remark || source?.name || source?.content || '日程便签';

      return snapshot.scheduleItems.map(schedule => {
        const tagIds = getFolderTagIds(undefined, schedule.tagIds && schedule.tagIds.length > 0 ? schedule.tagIds : fallbackTagIds);
        const dayKey = schedule.startAt ? getLocalDateKey(schedule.startAt) : '';
        return {
          id: `${label}:${schedule.id}`,
          noteLabel: label,
          note: snapshot,
          item: source,
          schedule,
          title: schedule.text,
          sourceTitle,
          dayKey,
          tagIds,
          isUnscheduled: !dayKey,
        } as CalendarScheduleEvent;
      });
    });
  }, [openFloatingNoteEntries, items, noteManagerVersion]);

  const filteredCalendarEvents = useMemo(() => (
    calendarEvents.filter(event => {
      if (calendarTagFilter === 'all') return true;
      if (calendarTagFilter === 'untagged') return event.tagIds.length === 0;
      const folderScopeIds = getDrawerFolderScopeIds(folders, calendarTagFilter);
      return event.tagIds.some(tagId => folderScopeIds.has(tagId));
    })
  ), [calendarEvents, calendarTagFilter, folders]);
  const calendarTagOptions = useMemo(() => ([
    { value: 'all', label: '全部' },
    { value: 'untagged', label: '无标签' },
    ...orderedFolders.map(folder => ({ value: folder.id, label: getDrawerFolderPathName(folders, folder.id) })),
  ]), [folders, orderedFolders]);
  const calendarTagFilterLabel = calendarTagOptions.find(option => option.value === calendarTagFilter)?.label || '全部';
  const calendarScheduleNoteOptions = useMemo<RoundedSelectOption[]>(() => {
    const sourceById = new Map(items.map(item => [item.id, item]));
    const existing = openFloatingNoteEntries
      .filter(entry => (
        entry.snapshot?.type === 'text' &&
        entry.snapshot.noteMode === 'schedule' &&
        Array.isArray(entry.snapshot.scheduleItems)
      ))
      .map((entry, index) => {
        const snapshot = entry.snapshot!;
        const source = sourceById.get(snapshot.itemId);
        const title = snapshot.name || source?.remark || source?.name || `日程便签 ${index + 1}`;
        const count = snapshot.scheduleItems?.length || 0;
        return {
          value: entry.label,
          label: `${title}${count > 0 ? ` · ${count}` : ''}`,
        };
      });

    return [
      { value: CALENDAR_NEW_NOTE_TARGET, label: '新便签' },
      ...existing,
    ];
  }, [openFloatingNoteEntries, items, noteManagerVersion]);

  useEffect(() => {
    if (
      calendarTargetNoteLabel !== CALENDAR_NEW_NOTE_TARGET &&
      !calendarScheduleNoteOptions.some(option => option.value === calendarTargetNoteLabel)
    ) {
      setCalendarTargetNoteLabel(CALENDAR_NEW_NOTE_TARGET);
    }
  }, [calendarTargetNoteLabel, calendarScheduleNoteOptions]);

  const calendarEventsByDay = useMemo(() => {
    const map = new Map<string, CalendarScheduleEvent[]>();
    filteredCalendarEvents.forEach(event => {
      if (!event.dayKey) return;
      const list = map.get(event.dayKey) || [];
      list.push(event);
      map.set(event.dayKey, list);
    });
    map.forEach(list => list.sort(compareCalendarEvents));
    return map;
  }, [filteredCalendarEvents]);

  const selectedCalendarEvents = calendarEventsByDay.get(getLocalDateKey(calendarSelectedDate)) || [];
  const unscheduledCalendarEvents = filteredCalendarEvents
    .filter(event => event.isUnscheduled)
    .sort(compareCalendarEvents);
  const calendarOpenCount = filteredCalendarEvents.filter(event => !event.schedule.done).length;
  const selectedCalendarOpenCount = selectedCalendarEvents.filter(event => !event.schedule.done).length;
  const buildAgentCalendarEvents = (limit = 80) => (
    filteredCalendarEvents.slice(0, limit).map(event => ({
      id: event.id,
      noteLabel: event.noteLabel,
      scheduleId: event.schedule.id,
      title: event.title,
      done: !!event.schedule.done,
      priority: normalizeSchedulePriority(event.schedule.priority),
      startAt: event.schedule.startAt,
      tagIds: event.tagIds,
      sourceTitle: event.sourceTitle,
    }))
  );

  const sendSystemNotification = async (title: string, body: string, options: { silent?: boolean } = {}) => {
    try {
      await invoke('show_system_notification', { title, body });
      if (!options.silent) showToast('已发送 Windows 通知');
      return true;
    } catch (err) {
      console.error('Windows notification failed:', err);
      if (!options.silent) showToast('Windows 通知发送失败');
      return false;
    }
  };

  const testCanvasAiConnection = async () => {
    if (canvasAiUsesCloudImageModels) {
      setIsTestingCanvasAiConnection(true);
      try {
        const result = await invoke<CloudImageModelsResult>('get_cloud_image_models', {
          provider: effectiveCanvasAiProvider,
        });
        const channels = result.channels || [];
        const successfulChannels = channels.filter(channel => !channel.error);
        const models = Array.from(new Set((channels.length > 0
          ? successfulChannels.flatMap(channel => channel.models || [])
          : result.models || []).map(model => model.trim()).filter(Boolean)));
        if (channels.length > 0 && successfulChannels.length === 0) {
          throw new Error(channels.map(channel => `${channel.name}：${channel.error || '读取失败'}`).join('；'));
        }
        setCanvasAiCloudImageModels({ ...result, models });
        showToast(channels.length > 0
          ? `连接成功，读取到 ${successfulChannels.length}/${channels.length} 条生图渠道、${models.length} 个模型`
          : `连接成功，读取到 ${models.length} 个模型`);
      } catch (error) {
        showToast(`授权钱包渠道测试失败：${String(error)}`);
      } finally {
        setIsTestingCanvasAiConnection(false);
      }
      return;
    }
    const endpoint = getCanvasAiEndpointForModels(
      effectiveCanvasAiProvider,
      effectiveCanvasAiEndpoint || canvasAiEndpoint,
    ).trim();
    const apiKey = isCanvasAiLicenseManaged ? '' : canvasAiApiKey.trim();
    if (!endpoint || (!apiKey && !isCanvasAiLicenseManaged)) {
      showToast('请先填写 Canvas API Base URL 和 API Key');
      return;
    }
    setIsTestingCanvasAiConnection(true);
    try {
      const result = await invoke<{ message: string }>('test_canvas_api_connection', {
        endpoint,
        apiKey,
        gatewayKind: effectiveCanvasAiGatewayKind,
        provider: effectiveCanvasAiApiProvider,
        model: effectiveCanvasAiModel,
        headers: isCanvasAiLicenseManaged ? undefined : parseCanvasAiHeaders(canvasAiHeadersText),
      });
      showToast(result.message || 'Canvas API 连接成功');
    } catch (error) {
      showToast(`Canvas API 连接失败：${String(error)}`);
    } finally {
      setIsTestingCanvasAiConnection(false);
    }
  };

  const notifyCanvasAiGenerationResult = (options: {
    status: 'success' | 'partial' | 'error';
    label: string;
    mediaType: 'image' | 'video';
    generatedCount?: number;
    requestedCount?: number;
    error?: string;
  }) => {
    const label = (options.label || 'AI 节点').trim();
    const unit = options.mediaType === 'video' ? '条视频' : '张图片';
    const generatedCount = Math.max(0, Math.round(Number(options.generatedCount || 0)));
    const requestedCount = Math.max(0, Math.round(Number(options.requestedCount || 0)));
    const title = options.status === 'success'
      ? `${label}生成完成`
      : options.status === 'partial'
        ? `${label}部分完成`
        : `${label}生成失败`;
    const body = options.status === 'success'
      ? `已生成 ${generatedCount} ${unit}，结果已保存到抽屉。`
      : options.status === 'partial'
        ? `已生成 ${generatedCount}/${requestedCount || generatedCount} ${unit}，部分输出失败。`
        : (options.error || '生成失败，请打开灵感抽屉查看详情。');
    void sendSystemNotification(title, body, { silent: true });
  };

  useEffect(() => {
    if (!calendarNotificationsEnabled) return;

    const checkTodaySchedules = () => {
      const now = Date.now();
      const hour = new Date(now).getHours();
      const notificationHour = [...CALENDAR_NOTIFICATION_HOURS]
        .reverse()
        .find(candidate => hour >= candidate);
      if (!notificationHour) return;

      const todayKey = getLocalDateKey(now);
      const dueEvents = (calendarEventsByDay.get(todayKey) || []).filter(event => !event.schedule.done);
      if (dueEvents.length === 0) return;

      const storageKey = `${CALENDAR_NOTIFICATION_SENT_STORAGE_PREFIX}${todayKey}_${notificationHour}`;
      if (localStorage.getItem(storageKey) === 'sent') return;

      sendSystemNotification(
        `今天有 ${dueEvents.length} 项日程`,
        getCalendarNotificationBody(dueEvents),
        { silent: true },
      ).then(sent => {
        if (sent) localStorage.setItem(storageKey, 'sent');
      });
    };

    checkTodaySchedules();
    const timer = window.setInterval(checkTodaySchedules, 60_000);
    return () => window.clearInterval(timer);
  }, [calendarNotificationsEnabled, calendarEventsByDay]);

  const calendarMonthDays = useMemo(() => {
    const monthDate = new Date(calendarMonth);
    const firstOfMonth = new Date(monthDate.getFullYear(), monthDate.getMonth(), 1);
    const firstOffset = firstOfMonth.getDay();
    const gridStart = addLocalDays(firstOfMonth.getTime(), -firstOffset);
    return Array.from({ length: 42 }, (_, index) => addLocalDays(gridStart, index));
  }, [calendarMonth]);

  const patchCalendarScheduleItem = async (
    noteLabel: string,
    scheduleId: string,
    patch: Partial<FloatingNoteScheduleItem>,
  ) => {
    const snapshot = readFloatingNoteSnapshot(noteLabel);
    if (!snapshot || !Array.isArray(snapshot.scheduleItems)) return;
    pushDrawerUndoSnapshot('修改日程');
    const next = {
      ...snapshot,
      noteMode: 'schedule' as const,
      scheduleItems: snapshot.scheduleItems.map(item => (
        item.id === scheduleId ? { ...item, ...patch, updatedAt: Date.now() } : item
      )),
      updatedAt: Date.now(),
    };
    await syncCalendarScheduleSnapshot(noteLabel, next);
  };

  const syncCalendarScheduleSnapshot = async (noteLabel: string, snapshot: FloatingNoteSnapshot) => {
    const content = snapshot.type === 'text' && snapshot.noteMode === 'schedule'
      ? getScheduleTextContent(snapshot.scheduleItems)
      : (snapshot.content || '');
    const next = {
      ...snapshot,
      content,
      updatedAt: Date.now(),
    } as FloatingNoteSnapshot;

    localStorage.setItem(floatingNoteStorageKey(noteLabel), JSON.stringify(next));
    if (next.type === 'text') {
      setItems(prev => {
        let found = false;
        const updated = prev.map(item => {
          if (item.id !== next.itemId || item.type !== 'text') return item;
          found = true;
          return {
            ...item,
            type: 'text',
            content,
            name: next.name || item.name || '日程便签',
            url: undefined,
            path: undefined,
            sourceUrl: undefined,
            pageUrl: undefined,
            originalUrl: undefined,
            isUrl: false,
          } as BufferItem;
        });

        if (found || !next.itemId.startsWith('calendar_schedule_')) return updated;
        return [{
          id: next.itemId,
          type: 'text',
          content,
          name: next.name || '日程便签',
          remark: next.name || '日程便签',
          remarks: next.name ? [next.name] : undefined,
          createdAt: next.createdAt || Date.now(),
          folderId: next.folderId,
        } as BufferItem, ...updated];
      });
    }
    await emitFloatingNoteUpdated(noteLabel, next).catch(() => {});
    refreshNoteManager();
    return next;
  };

  const deleteCalendarScheduleItem = async (event: CalendarScheduleEvent) => {
    const snapshot = readFloatingNoteSnapshot(event.noteLabel);
    if (!snapshot || !Array.isArray(snapshot.scheduleItems)) return;
    pushDrawerUndoSnapshot('删除日程');

    const next = {
      ...snapshot,
      noteMode: 'schedule' as const,
      scheduleItems: snapshot.scheduleItems.filter(item => item.id !== event.schedule.id),
      updatedAt: Date.now(),
    };
    await syncCalendarScheduleSnapshot(event.noteLabel, next);
  };

  const ensureCalendarScheduleNote = (targetLabel = calendarTargetNoteLabel) => {
    if (targetLabel !== CALENDAR_NEW_NOTE_TARGET) {
      const target = openFloatingNoteEntries.find(entry => entry.label === targetLabel);
      const snapshot = readFloatingNoteSnapshot(targetLabel) || target?.snapshot;
      if (
        snapshot?.type === 'text' &&
        snapshot.noteMode === 'schedule' &&
        Array.isArray(snapshot.scheduleItems)
      ) {
        return { label: targetLabel, snapshot };
      }
      setCalendarTargetNoteLabel(CALENDAR_NEW_NOTE_TARGET);
      showToast('这个日程便签不可用，已改为新建');
    }

    const openLabels = readOpenFloatingNoteLabels();
    const label = FLOATING_NOTE_LABELS.find(item => !openLabels.includes(item));
    if (!label) {
      showToast(`最多同时保存 ${MAX_FLOATING_NOTE_COUNT} 个桌面便签，请先关闭一个`);
      return null;
    }

    const now = Date.now();
    const tagIds = calendarTagFilter !== 'all' && calendarTagFilter !== 'untagged' ? [calendarTagFilter] : [];
    const snapshot: FloatingNoteSnapshot = {
      id: `calendar_schedule_${now}`,
      itemId: `calendar_schedule_${now}`,
      type: 'text',
      name: '日程便签',
      content: '',
      noteMode: 'schedule',
      scheduleItems: [],
      tagIds,
      createdAt: now,
      updatedAt: now,
      width: TEXT_FLOATING_NOTE_SIZES.large.width,
      height: TEXT_FLOATING_NOTE_SIZES.large.height,
    };

    localStorage.setItem(floatingNoteStorageKey(label), JSON.stringify(snapshot));
    rememberOpenFloatingNoteLabel(label);
    return { label, snapshot };
  };

  const addCalendarScheduleItem = async () => {
    const text = calendarDraftText.trim();
    if (!text) return;

    const requestedTargetLabel = calendarTargetNoteLabel;
    const target = ensureCalendarScheduleNote(requestedTargetLabel);
    if (!target) return;
    pushDrawerUndoSnapshot('新增日程');

    const tagIds = calendarTagFilter === 'untagged'
      ? []
      : (calendarTagFilter !== 'all'
        ? [calendarTagFilter]
        : getFolderTagIds(target.snapshot.folderId, target.snapshot.tagIds));
    const now = Date.now();
    const nextItem: FloatingNoteScheduleItem = {
      id: `schedule_${now}_${Math.random().toString(36).slice(2, 7)}`,
      text,
      done: false,
      priority: calendarDraftPriority,
      startAt: startOfLocalDay(calendarSelectedDate),
      allDay: true,
      tagIds,
      sourceItemId: target.snapshot.itemId,
      createdAt: now,
    };
    const next = {
      ...target.snapshot,
      type: 'text' as const,
      noteMode: 'schedule' as const,
      scheduleItems: [...(target.snapshot.scheduleItems || []), nextItem],
      updatedAt: now,
    };

    await syncCalendarScheduleSnapshot(target.label, next);
    if (requestedTargetLabel === CALENDAR_NEW_NOTE_TARGET) {
      setCalendarTargetNoteLabel(target.label);
    }
    setCalendarDraftText('');
  };

  const moveCalendarMonth = (delta: number) => {
    setCalendarMonth(prev => {
      const date = new Date(prev);
      return new Date(date.getFullYear(), date.getMonth() + delta, 1).getTime();
    });
  };

  const jumpCalendarToday = () => {
    const today = startOfLocalDay(Date.now());
    setCalendarMonth(today);
    setCalendarSelectedDate(today);
  };

  const getCalendarTagName = (tagId?: string) => {
    if (!tagId) return '无标签';
    return getDrawerFolderPathName(folders, tagId) || '未知标签';
  };

  const renderCalendarEvent = (event: CalendarScheduleEvent) => {
    const primaryTagId = event.tagIds[0];
    const priority = normalizeSchedulePriority(event.schedule.priority);
    return (
      <div
        key={event.id}
        data-calendar-event="true"
        className="group/calendar-event rounded-[14px] border border-stone-200 bg-white px-3 py-2.5 shadow-none transition-[background-color,border-color] hover:border-stone-300 hover:bg-stone-50/80 dark:border-stone-700 dark:bg-stone-900/72 dark:hover:border-stone-600 dark:hover:bg-stone-800/72"
      >
        <div className="flex items-start gap-2">
          <button
            type="button"
            onClick={() => patchCalendarScheduleItem(event.noteLabel, event.schedule.id, { done: !event.schedule.done })}
            className={`mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center rounded-[6px] border transition-colors ${
              event.schedule.done
                ? 'border-stone-800 bg-stone-800 text-white dark:border-stone-100 dark:bg-stone-100 dark:text-stone-900'
                : 'border-stone-300 bg-white/75 text-transparent dark:border-stone-600 dark:bg-stone-950'
            }`}
            title={event.schedule.done ? '标记为未完成' : '标记为完成'}
          >
            <Check className="h-3 w-3" strokeWidth={3} />
          </button>
          <button
            type="button"
            onClick={() => focusFloatingNote(event.noteLabel, event.note)}
            className="min-w-0 flex-1 text-left"
            title="打开来源便签"
          >
            <div className="flex min-w-0 items-center gap-1.5">
              <span
                data-calendar-priority={priority}
                className="inline-flex h-4 min-w-4 shrink-0 items-center justify-center rounded-[5px] px-1 text-[9px] font-black leading-none"
              >
                {priority}
              </span>
              <div className={`min-w-0 flex-1 truncate text-xs font-bold ${event.schedule.done ? 'text-stone-400 line-through dark:text-stone-500' : 'text-stone-800 dark:text-stone-100'}`}>
                {event.title}
              </div>
            </div>
            <div className="mt-1 flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1 text-[10px] font-semibold">
              <span className="inline-flex items-center gap-1 text-stone-500 dark:text-stone-400">
                <Clock className="h-3 w-3" />
                {formatScheduleDateLabel(event.schedule.startAt)}
              </span>
              <span className="inline-flex items-center gap-1 text-stone-500 dark:text-stone-400">
                <Tag className="h-3 w-3" />
                {getCalendarTagName(primaryTagId)}
              </span>
              <span className="min-w-0 truncate text-stone-400/90 dark:text-stone-500">{event.sourceTitle}</span>
            </div>
          </button>
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              deleteCalendarScheduleItem(event);
            }}
            className="shrink-0 rounded-[10px] p-1 text-stone-300 opacity-70 transition-all hover:bg-red-50 hover:text-red-500 hover:opacity-100 dark:text-stone-600 dark:hover:bg-red-900/25 dark:hover:text-red-300"
            title="删除待办"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        </div>
      </div>
    );
  };

  const ensureCanvasAiGeneratedFolder = (canvasId?: string | null) => {
    const normalizedCanvasId = canvasId?.trim() || DEFAULT_CANVAS_ID;
    const canvasName = canvasesRef.current.find(canvas => canvas.id === normalizedCanvasId)?.name;
    const current = ensureCanvasGeneratedImageFolders(
      foldersRef.current,
      normalizedCanvasId,
      canvasName,
    );
    if (current.folders === foldersRef.current) return current.folderId;

    foldersRef.current = current.folders;
    setFolders(prev => {
      const ensured = ensureCanvasGeneratedImageFolders(
        prev,
        normalizedCanvasId,
        canvasName,
      );
      if (ensured.folders === prev) return prev;
      foldersRef.current = ensured.folders;
      persistFoldersSnapshot(ensured.folders);
      return ensured.folders;
    });
    return current.folderId;
  };

  const ensureAiGeneratedVideoFolder = () => {
    const existing = foldersRef.current.find(folder => folder.name === AI_GENERATED_VIDEO_FOLDER_NAME);
    if (existing) return existing.id;

    const newFolder: Folder = {
      id: AI_GENERATED_VIDEO_FOLDER_ID,
      name: AI_GENERATED_VIDEO_FOLDER_NAME,
      color: AI_GENERATED_VIDEO_FOLDER_COLOR,
    };
    setFolders(prev => {
      if (prev.some(folder => folder.id === newFolder.id || folder.name === newFolder.name)) return prev;
      const nextFolders = insertDrawerFolderAtTop(prev, newFolder);
      persistFoldersSnapshot(nextFolders);
      return nextFolders;
    });
    return newFolder.id;
  };

  const addGeneratedImagesToDrawer = (
    generatedItems: BufferItem[],
    options?: {
      canvasId?: string;
      onOutputCachePatch?: (
        outputId: string,
        matchSources: string[],
        patch: Partial<CanvasAiGeneratedOutput>
      ) => void;
      canvasOutputClientRequestId?: string;
    }
  ) => {
    if (isCanvasInteractingRef.current || isCanvasZoomingRef.current || canvasPanRef.current) {
      window.setTimeout(() => addGeneratedImagesToDrawer(generatedItems, options), 180);
      return;
    }
    const cleanItems = generatedItems.filter(item => item.type === 'image');
    if (cleanItems.length === 0) return;

    const folderId = ensureCanvasAiGeneratedFolder(
      options?.canvasId || activeCanvasIdRef.current || DEFAULT_CANVAS_ID,
    );
    const now = Date.now();
    const savedItems = cleanItems.map((item, index) => {
      const savedItem = stripHeavyDataThumbnail(item);
      const { remark: _promptRemark, remarks: _promptRemarks, ...itemWithoutPromptNotes } = savedItem;
      return {
        ...itemWithoutPromptNotes,
        folderId,
        createdAt: item.createdAt || now + index,
        isQuickAccess: false,
      } as BufferItem;
    });
    const savedIds = new Set(savedItems.map(item => item.id));
    savedItems.forEach((item) => {
      if (shouldCacheGeneratedImageAgain(item)) {
        generatedImageCachePendingIdsRef.current.add(item.id);
      }
    });
    updateDrawerItemsDeferred(prev => [
      ...savedItems.filter(item => !prev.some(existing => existing.id === item.id)),
      ...prev,
    ]);
    const latestCacheDir = (
      webImageCacheDirRef.current ||
      localStorage.getItem('drawer_web_image_cache_dir') ||
      ''
    ).trim();

    savedItems.forEach((item) => {
      const source = getGeneratedImageCacheSource(item);
      if (!source) return;
      if (!shouldCacheGeneratedImageAgain(item)) {
        if (item.thumbnail) return;
        const localPreviewSource = item.url || (item.path ? convertFileSrc(item.path) : source);
        enqueueCanvasAiOutputThumbnailJob({
          key: `drawer-local:${item.id}:${item.path || localPreviewSource}`,
          outputId: item.id,
          drawerItemId: item.id,
          source: localPreviewSource,
          path: item.path,
        });
        return;
      }

      const patchMatchingOutputs = (patch: Partial<CanvasAiGeneratedOutput>, matchSources = [source]) => {
        const sourceSet = new Set(matchSources.filter(Boolean));
        if (!options?.onOutputCachePatch) {
          updateCanvasItemsImmediate(prev => prev.map(canvasItem => {
            if (!canvasItem.ai?.outputs?.length) return canvasItem;
            let changed = false;
            const outputs = canvasItem.ai.outputs.map((output) => {
              const outputSource = getCanvasAiOutputDisplaySource(output);
              const matchesOutput = output.id === item.id || sourceSet.has(outputSource);
              const matchesGeneration = !options?.canvasOutputClientRequestId
                || output.id === item.id
                || output.clientRequestId === options.canvasOutputClientRequestId
                || output.taskId === options.canvasOutputClientRequestId;
              if (!matchesOutput || !matchesGeneration) return output;
              changed = true;
              return recoverCanvasAiOutputWithUsableResult({ ...output, ...patch });
            });
            return changed
              ? recoverCanvasAiNodeWithUsableResults({ ...canvasItem, ai: { ...canvasItem.ai, outputs } })
              : canvasItem;
          }));
        }
        options?.onOutputCachePatch?.(item.id, Array.from(sourceSet), patch);
      };

      const cacheGeneratedImage = async () => {
        let lastError: unknown = new Error('网页图片缓存没有返回文件路径');
        const retryDelays = /^https?:\/\//i.test(source)
          ? GENERATED_IMAGE_CACHE_RETRY_DELAYS_MS
          : [];
        for (let attempt = 0; attempt <= retryDelays.length; attempt += 1) {
          try {
            const cachedPath = await invoke<string>('cache_web_image', {
              // Keep the stable result URL intact. The native downloader follows
              // its short-lived HTTPS storage redirect without exposing that URL.
              url: source,
              name: item.name || item.content || AI_GENERATED_FOLDER_NAME,
              dir: latestCacheDir || undefined,
            });
            if (cachedPath) return cachedPath;
            lastError = new Error('网页图片缓存没有返回文件路径');
          } catch (err) {
            lastError = err;
          }
          if (attempt < retryDelays.length) {
            await new Promise<void>(resolve => window.setTimeout(resolve, retryDelays[attempt]));
          }
        }
        throw lastError;
      };

      const cachePromise = cacheGeneratedImage();
      generatedImageCachePromisesRef.current.set(source, cachePromise);
      cachePromise
        .then((cachedPath) => {
          if (!cachedPath) {
            generatedImageCachePendingIdsRef.current.delete(item.id);
            updateDrawerItemsDeferred(prev => prev.map(existing => existing.id === item.id ? { ...existing } : existing));
            patchMatchingOutputs({ cacheStatus: 'failed' });
            return;
          }
          const cachedUrl = convertFileSrc(cachedPath);
          const sourceIsDataImage = isDataImageSourceValue(source);
          const originalUrl = sourceIsDataImage || isDataImageSourceValue(item.originalUrl)
            ? undefined
            : item.originalUrl || source;
          const cachedItem = {
            ...item,
            url: cachedUrl,
            path: cachedPath,
            sourceUrl: sourceIsDataImage ? undefined : source,
            originalUrl,
          } as BufferItem;
          updateDrawerItemsDeferred(prev => prev.map(existing => existing.id === item.id ? cachedItem : existing));
          if (!options?.onOutputCachePatch) {
            updateCanvasItemsImmediate(prev => prev.map(canvasItem => (
              canvasItem.item.id === item.id
                ? { ...canvasItem, item: cachedItem }
                : canvasItem
            )));
          }
          const matchSources = [source, cachedUrl];
          patchMatchingOutputs(buildCanvasAiOutputLocalCachePatch(cachedPath), matchSources);
          enqueueCanvasAiOutputThumbnailJob({
            key: `output:${item.id}:${cachedPath}`,
            outputId: item.id,
            matchSources,
            drawerItemId: item.id,
            source: cachedUrl,
            path: cachedPath,
            onSettled: (patch) => {
              options?.onOutputCachePatch?.(item.id, matchSources, patch);
            },
          });
        })
        .catch((err) => {
          console.warn('AI 生图缓存失败:', err);
          generatedImageCachePendingIdsRef.current.delete(item.id);
          updateDrawerItemsDeferred(prev => prev.map(existing => existing.id === item.id
            ? {
              ...existing,
              url: source,
              sourceUrl: source,
              originalUrl: source,
            }
            : existing));
          patchMatchingOutputs({
            url: source,
            sourceUrl: source,
            cacheStatus: 'failed',
          });
        })
        .finally(() => {
          if (generatedImageCachePromisesRef.current.get(source) === cachePromise) {
            generatedImageCachePromisesRef.current.delete(source);
          }
        });
    });

    if (savedIds.size > 0) {
      startTransition(() => {
        setActiveFolderId(folderId);
        setActiveTab('image');
      });
    }
  };

